window.H=window.H||{};H[27]={"27회-2차-041":{"한줄":"송수관·송유관 및 저장시설의 부지는 광천지에서 제외되므로(영 제58조제6호 단서) 이를 광천지로 한다는 ②가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제6호","원문":"광천지: 지하에서 온수ㆍ약수ㆍ석유류 등이 용출되는 용출구(湧出口)와 그 유지(維持)에 사용되는 부지. 다만, 온수ㆍ약수ㆍ석유류 등을 일정한 장소로 운송하는 송수관ㆍ송유관 및 저장시설의 부지는 제외한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제59조제1항","원문":"법 제67조제1항에 따른 지목의 설정은 다음 각 호의 방법에 따른다. 1. 필지마다 하나의 지목을 설정할 것 2. 1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정할 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제59조제2항","원문":"토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 아니한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제64조","원문":"지목을 지적도 및 임야도(이하 \"지적도면\"이라 한다)에 등록하는 때에는 다음의 부호로 표기하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지목을 지적도 및 임야도에 등록할 때에는 부호로 표기한다(규칙 제64조)."},{"번호":2,"판정":"틀림","설명":"광천지는 용출구와 그 유지에 사용되는 부지다. 온수·약수·석유류 등을 운송하는 송수관·송유관 및 저장시설의 부지는 광천지에서 제외된다(영 제58조제6호 단서)."},{"번호":3,"판정":"옳음","설명":"필지마다 하나의 지목을 설정한다(영 제59조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"1필지가 둘 이상의 용도로 활용되면 주된 용도에 따라 지목을 설정한다(영 제59조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 않는다(영 제59조제2항)."}],"개념":[{"종류":"표","제목":"지목 설정 원칙(영 제59조)","머리":["구분","내용"],"행":[["1필지 1지목","필지마다 하나의 지목을 설정"],["복합 용도","1필지가 둘 이상의 용도로 활용되면 주된 용도에 따라 설정"],["일시적·임시적 용도","지목을 변경하지 않음"],["지적도면 표기","부호로 표기(규칙 제64조)"]]},{"종류":"표","제목":"물·시설 부지 지목 구분(영 제58조)","머리":["지목","포함","제외·주의"],"행":[["광천지","온수·약수·석유류 등이 용출되는 용출구와 그 유지에 사용되는 부지","송수관·송유관·저장시설의 부지는 제외"],["수도용지","물을 정수하여 공급하기 위한 취수·저수·도수·정수·송수 및 배수 시설의 부지와 접속 부속시설물의 부지","-"],["유지","물이 고이거나 상시 물을 저장하는 댐·저수지·소류지·호수·연못 등과 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지","연·왕골 등을 상시 직접 이용하여 재배하면 답"],["답","물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지","-"],["구거","용수·배수를 위한 인공 수로·둑·부속시설물의 부지, 유수가 있거나 있을 것으로 예상되는 소규모 수로부지","-"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","-"],["양어장","육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지와 접속 부속시설물의 부지","-"]]}],"함정":"②는 광천지 정의에서 단서를 빼고 쓴 문장이다. 송수관·송유관·저장시설의 부지는 용출구와 달리 광천지 범위에서 빠진다."},"27회-2차-042":{"한줄":"묘지의 관리를 위한 건축물의 부지는 묘지에서 제외되어 \"대\"로 하므로(영 제58조제27호 단서) ③이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제27호","원문":"묘지: 사람의 시체나 유골이 매장된 토지, 「도시공원 및 녹지 등에 관한 법률」에 따른 묘지공원으로 결정ㆍ고시된 토지 및 「장사 등에 관한 법률」 제2조제9호에 따른 봉안시설과 이에 접속된 부속시설물의 부지. 다만, 묘지의 관리를 위한 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제10호","원문":"학교용지: 학교의 교사(校舍)와 이에 접속된 체육장 등 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제13호","원문":"창고용지: 물건 등을 보관하거나 저장하기 위하여 독립적으로 설치된 보관시설물의 부지와 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제15호","원문":"철도용지: 교통 운수를 위하여 일정한 궤도 등의 설비와 형태를 갖추어 이용되는 토지와 이에 접속된 역사(驛舍)ㆍ차고ㆍ발전시설 및 공작창(工作廠) 등 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제20호","원문":"양어장: 육상에 인공으로 조성된 수산생물의 번식 또는 양식을 위한 시설을 갖춘 부지와 이에 접속된 부속시설물의 부지"}],"선지":[{"번호":1,"판정":"옳음","설명":"학교의 교사와 이에 접속된 체육장 등 부속시설물의 부지는 학교용지다(영 제58조제10호)."},{"번호":2,"판정":"옳음","설명":"독립적으로 설치된 보관시설물의 부지와 접속 부속시설물의 부지는 창고용지다(영 제58조제13호)."},{"번호":3,"판정":"틀림","설명":"묘지에는 매장 토지, 묘지공원으로 결정·고시된 토지, 봉안시설과 접속 부속시설물의 부지가 들어간다. 묘지의 관리를 위한 건축물의 부지는 \"대\"다(영 제58조제27호 단서)."},{"번호":4,"판정":"옳음","설명":"일정한 궤도 등의 설비와 형태를 갖춘 토지와 접속된 역사·차고·발전시설·공작창 등의 부지는 철도용지다(영 제58조제15호)."},{"번호":5,"판정":"옳음","설명":"육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지와 접속 부속시설물의 부지는 양어장이다(영 제58조제20호)."}],"개념":[{"종류":"표","제목":"주거용·관리용 건축물 부지가 \"대\"가 되는 지목(영 제58조 단서)","머리":["지목","단서 내용"],"행":[["과수원","주거용 건축물의 부지는 \"대\""],["목장용지","주거용 건축물의 부지는 \"대\""],["묘지","묘지의 관리를 위한 건축물의 부지는 \"대\""],["사적지","학교용지·공원·종교용지 등 다른 지목으로 된 토지 안의 유적 보호 구획은 제외"],["염전","동력으로 바닷물을 끌어들여 소금을 제조하는 공장시설물의 부지는 제외"]]}],"함정":"③은 묘지의 범위를 관리용 건축물 부지까지 넓혀 놓은 지문이다. 봉안시설 부지는 묘지, 관리용 건축물 부지는 대로 갈린다."},"27회-2차-045":{"한줄":"도시개발사업 등이 준공되기 전에 지번을 부여할 때는 사업계획도에 따르므로 ( )에는 사업계획도가 들어간다(규칙 제61조).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제61조","원문":"지적소관청은 영 제56조제4항에 따라 도시개발사업 등이 준공되기 전에 지번을 부여하는 때에는 제95조제1항제3호의 사업계획도에 따르되, 영 제56조제3항제5호에 따라 부여하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제56조제4항","원문":"법 제86조에 따른 도시개발사업 등이 준공되기 전에 사업시행자가 지번부여 신청을 하면 국토교통부령으로 정하는 바에 따라 지번을 부여할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제56조제3항제5호","원문":"지적확정측량을 실시한 지역의 각 필지에 지번을 새로 부여하는 경우에는 다음 각 목의 지번을 제외한 본번으로 부여할 것. 다만, 부여할 수 있는 종전 지번의 수가 새로 부여할 지번의 수보다 적을 때에는 블록 단위로 하나의 본번을 부여한 후 필지별로 부번을 부여하거나, 그 지번부여지역의 최종 본번 다음 순번부터 본번으로 하여 차례로 지번을 부여할 수 있다. 가. 지적확정측량을 실시한 지역의 종전의 지번과 지적확정측량을 실시한 지역 밖에 있는 본번이 같은 지번이 있을 때에는 그 지번 나. 지적확정측량을 실시한 지역의 경계에 걸쳐 있는 지번"}],"선지":[{"번호":1,"판정":"옳음","설명":"도시개발사업 등 준공 전 지번부여는 규칙 제95조제1항제3호의 사업계획도에 따른다(규칙 제61조)."},{"번호":2,"판정":"틀림","설명":"준공 전 지번부여는 사업계획도에 따른다. 사업인가서는 기준이 아니다(규칙 제61조)."},{"번호":3,"판정":"틀림","설명":"준공 전 지번부여는 사업계획도에 따른다. 지적도는 기준이 아니다(규칙 제61조)."},{"번호":4,"판정":"틀림","설명":"준공 전 지번부여는 사업계획도에 따른다. 토지대장은 기준이 아니다(규칙 제61조)."},{"번호":5,"판정":"틀림","설명":"준공 전 지번부여는 사업계획도에 따른다. 토지분할조서는 기준이 아니다(규칙 제61조)."}],"개념":[{"종류":"흐름","제목":"도시개발사업 등 준공 전 지번부여","단계":[{"이름":"신청","설명":"사업시행자가 도시개발사업 등이 준공되기 전에 지번부여를 신청(영 제56조제4항)"},{"이름":"기준","설명":"지적소관청이 사업계획도에 따른다(규칙 제61조)"},{"이름":"부여 방법","설명":"지적확정측량을 실시한 지역의 지번부여 방법에 따라 부여(영 제56조제3항제5호)"}]},{"종류":"표","제목":"지적확정측량 지역의 지번부여 방법을 준용하는 경우(영 제56조제3항제6호)","머리":["목","준용 사유"],"행":[["가","법 제66조제2항에 따라 지번부여지역의 지번을 변경할 때"],["나","법 제85조제2항에 따른 행정구역 개편에 따라 새로 지번을 부여할 때"],["다","영 제72조제1항에 따라 축척변경 시행지역의 필지에 지번을 부여할 때"]]}],"함정":"준공 전에는 지적공부에 해당 필지가 등록되어 있지 않아 지적도나 토지대장이 기준이 될 수 없다. 기준은 사업계획도이고 부여 방법은 지적확정측량 지역의 방식이다."},"27회-2차-051":{"한줄":"합병에 따른 경계·좌표 또는 면적은 따로 지적측량을 하지 않고 결정하므로(법 제26조제1항) 지적측량을 하여 결정한다는 ④가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제26조제1항","원문":"합병에 따른 경계ㆍ좌표 또는 면적은 따로 지적측량을 하지 아니하고 다음 각 호의 구분에 따라 결정한다. 1. 합병 후 필지의 경계 또는 좌표: 합병 전 각 필지의 경계 또는 좌표 중 합병으로 필요 없게 된 부분을 말소하여 결정 2. 합병 후 필지의 면적: 합병 전 각 필지의 면적을 합산하여 결정"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제66조제1항","원문":"지번은 지적소관청이 지번부여지역별로 차례대로 부여한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제63조","원문":"지적소관청은 행정구역의 변경, 도시개발사업의 시행, 지번변경, 축척변경, 지번정정 등의 사유로 지번에 결번이 생긴 때에는 지체 없이 그 사유를 별지 제61호서식의 결번대장에 적어 영구히 보존하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제69조제2항","원문":"지적공부를 정보처리시스템을 통하여 기록ㆍ저장한 경우 관할 시ㆍ도지사, 시장ㆍ군수 또는 구청장은 그 지적공부를 지적정보관리체계에 영구히 보존하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지번은 지적소관청이 지번부여지역별로 차례대로 부여한다(법 제66조제1항)."},{"번호":2,"판정":"옳음","설명":"결번이 생기면 지체 없이 그 사유를 결번대장에 적어 영구히 보존한다(규칙 제63조)."},{"번호":3,"판정":"옳음","설명":"토지의 이동에 따라 지상경계를 새로 정하면 지상경계점등록부를 작성·관리한다(법 제65조제2항)."},{"번호":4,"판정":"틀림","설명":"합병 후 경계 또는 좌표는 합병 전 각 필지의 경계 또는 좌표 중 필요 없게 된 부분을 말소하여, 면적은 합병 전 면적을 합산하여 결정한다. 지적측량을 하지 않는다(법 제26조제1항)."},{"번호":5,"판정":"옳음","설명":"정보처리시스템으로 기록·저장한 지적공부는 지적정보관리체계에 영구 보존한다(법 제69조제2항)."}],"개념":[{"종류":"표","제목":"토지의 이동에 따른 측량 여부와 면적 결정","머리":["구분","결정 방법"],"행":[["합병","지적측량 없이 경계·좌표는 불필요한 부분 말소, 면적은 합산(법 제26조제1항)"],["등록전환·분할","면적 오차의 허용범위와 처리방법은 대통령령(법 제26조제2항, 영 제19조)"],["지번","지적소관청이 지번부여지역별로 차례대로 부여(법 제66조제1항)"],["결번","결번대장에 적어 영구 보존(규칙 제63조)"]]}],"함정":"합병은 새 경계선을 긋는 일이 없고 있던 선을 지우는 일이어서 측량 없이 처리된다. 분할·등록전환은 측량을 거치는 이동이다."},"27회-2차-043":{"한줄":"경계점좌표등록부 지역은 제곱미터 이하 한 자리 단위로 결정하며 0.05제곱미터를 초과하는 끝수는 올리므로 1,029.551은 1,029.6이 된다(영 제60조제1항제2호).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제60조제1항제2호","원문":"지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소수 둘째 자리까지 쓴 값이다. 이 지역은 제곱미터 이하 한 자리 단위로 결정한다(영 제60조제1항제2호)."},{"번호":2,"판정":"틀림","설명":"이 값도 소수 둘째 자리까지 쓴 값이다. 한 자리 단위로 결정한 값이 아니다(영 제60조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"0.1제곱미터 미만 끝수 0.051은 0.05제곱미터를 초과하므로 버리지 않고 올린다(영 제60조제1항제2호)."},{"번호":4,"판정":"옳음","설명":"0.1제곱미터 미만 끝수 0.051이 0.05제곱미터를 초과하므로 올려 1,029.6이다(영 제60조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"1제곱미터 단위(일반 지역의 방식)로 결정한 값이다. 경계점좌표등록부 지역은 한 자리 단위로 결정한다(영 제60조제1항제1호·제2호)."}],"개념":[{"종류":"계산","제목":"1,029.551제곱미터의 등록 면적","단계":[{"설명":"적용 규정 확인: 경계점좌표등록부 지역(영 제60조제1항제2호)","식":"제곱미터 이하 한 자리 단위","값":"소수 첫째 자리까지"},{"설명":"0.1제곱미터 미만의 끝수 구하기","식":"1,029.551 - 1,029.5","값":"0.051"},{"설명":"끝수와 0.05 비교","식":"0.051 > 0.05","값":"올림"},{"설명":"등록 면적","식":"1,029.5 + 0.1","값":"1,029.6"}]},{"종류":"표","제목":"면적 끝수 처리(영 제60조제1항)","머리":["지역","단위","끝수 처리"],"행":[["일반 지역","1제곱미터","0.5 미만 버림, 0.5 초과 올림, 0.5이면 앞자리가 0 또는 짝수면 버리고 홀수면 올림. 1필지가 1제곱미터 미만이면 1제곱미터"],["지적도 축척 600분의 1 지역, 경계점좌표등록부 지역","0.1제곱미터","0.05 미만 버림, 0.05 초과 올림, 0.05이면 앞자리가 0 또는 짝수면 버리고 홀수면 올림. 1필지가 0.1제곱미터 미만이면 0.1제곱미터"]]}],"함정":"끝수 0.051은 정확히 0.05가 아니므로 짝수·홀수 규칙(0.05일 때만 적용)을 쓰지 않는다. 0.05를 초과하므로 올린다."},"27회-2차-044":{"한줄":"토지가 해면 또는 수면에 접하는 경우 지상 경계의 결정기준은 최대만조위 또는 최대만수위가 되는 선이므로(영 제55조제1항제4호) 평균해수면이라는 ②가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제65조제1항","원문":"토지의 지상경계는 둑, 담장이나 그 밖에 구획의 목표가 될 만한 구조물 및 경계점표지 등으로 구분한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제1항제4호","원문":"토지가 해면 또는 수면에 접하는 경우: 최대만조위 또는 최대만수위가 되는 선"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제1항제5호","원문":"공유수면매립지의 토지 중 제방 등을 토지에 편입하여 등록하는 경우: 바깥쪽 어깨부분"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제3항제4호","원문":"제65조제1항에 따라 토지를 분할하려는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제65조제1항제1호","원문":"소유권이전, 매매 등을 위하여 필요한 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제55조제4항","원문":"분할에 따른 지상 경계는 지상건축물을 걸리게 결정해서는 아니 된다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. 1. 법원의 확정판결이 있는 경우 2. 법 제87조제1호에 해당하는 토지를 분할하는 경우 3. 제3항제1호 또는 제3호에 따라 토지를 분할하는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"지상경계는 둑, 담장이나 그 밖에 구획의 목표가 될 만한 구조물 및 경계점표지 등으로 구분한다(법 제65조제1항)."},{"번호":2,"판정":"틀림","설명":"해면 또는 수면에 접하는 토지의 지상 경계는 최대만조위 또는 최대만수위가 되는 선이다(영 제55조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"분할에 따른 지상 경계는 지상건축물을 걸리게 결정할 수 없고, 법원의 확정판결이 있으면 예외다(영 제55조제4항제1호)."},{"번호":4,"판정":"옳음","설명":"소유권이전, 매매 등을 위한 분할은 영 제65조제1항제1호에 해당하고 이 경우 지상 경계점에 경계점표지를 설치하여 측량할 수 있다(영 제55조제3항제4호)."},{"번호":5,"판정":"옳음","설명":"공유수면매립지의 제방 등을 토지에 편입하여 등록하는 경우 바깥쪽 어깨부분이 기준이다(영 제55조제1항제5호)."}],"개념":[{"종류":"표","제목":"지상 경계의 결정기준(영 제55조제1항·제2항)","머리":["구분","결정기준"],"행":[["높낮이 차이 없음","구조물 등의 중앙"],["높낮이 차이 있음","구조물 등의 하단부"],["도로·구거 등의 절토(땅깎기) 부분","경사면의 상단부"],["해면 또는 수면에 접함","최대만조위 또는 최대만수위가 되는 선"],["공유수면매립지의 제방 등 편입","바깥쪽 어깨부분"],["구조물 등의 소유자가 다름","제1호~제3호에도 불구하고 소유권에 따라 결정(제2항)"]]},{"종류":"표","제목":"경계점표지를 설치하여 측량할 수 있는 분할(영 제55조제3항)","머리":["호","경우"],"행":[["1","도시개발사업 등의 사업시행자가 사업지구의 경계를 결정하기 위하여 분할"],["2","사업시행자와 행정기관의 장 또는 지방자치단체의 장이 토지를 취득하기 위하여 분할"],["3","도시·군관리계획 결정고시와 지형도면 고시가 된 지역의 도시·군관리계획선에 따른 분할"],["4","영 제65조제1항에 따른 분할(소유권이전, 매매 등을 위하여 필요한 경우 등)"],["5","관계 법령에 따라 인가·허가 등을 받아 분할"]]}],"함정":"해면에 접하는 토지는 최대만조위, 수면에 접하는 토지는 최대만수위로 정한다. 평균 수위나 최소 수위를 기준으로 쓴 선지는 틀리다."},"27회-2차-001":{"한줄":"ㄱ~ㄹ 네 보기가 모두 제2조 정의와 판례에 맞아 ㄱ, ㄴ, ㄷ, ㄹ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제2조제4호","원문":"\"개업공인중개사\"라 함은 이 법에 의하여 중개사무소의 개설등록을 한 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"판례":"대법원 판례(중개를 '업'으로 한다는 것)","요지":"우연한 기회에 단 1회 임대차 중개를 하고 보수를 받은 사실만으로는 중개를 업으로 한 것으로 볼 수 없다. 업으로 하려면 반복·계속하여 영업으로 할 의사나 객관적 사정이 있어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ과 ㄹ도 옳은 보기라 ㄱ, ㄴ만 고른 조합은 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄴ과 ㄹ도 옳은 보기라 ㄱ, ㄷ만 고른 조합은 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄷ도 옳다. 공인중개사로서 중개업무를 보조하는 자도 소속공인중개사다(제2조제5호)."},{"번호":4,"판정":"틀림","설명":"ㄱ도 옳다. 중개사무소 개설등록을 한 자가 개업공인중개사다(제2조제4호)."},{"번호":5,"판정":"옳음","설명":"네 보기가 모두 옳아 이 조합이 맞다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"개업공인중개사는 이 법에 의하여 중개사무소의 개설등록을 한 자다(제2조제4호)."},{"기호":"ㄴ","판정":"옳음","설명":"소속공인중개사에는 개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자가 포함된다(제2조제5호)."},{"기호":"ㄷ","판정":"옳음","설명":"소속공인중개사의 정의에 중개업무를 '보조하는 자'가 들어 있다(제2조제5호). 공인중개사가 아닌 보조자는 중개보조원이다(제2조제6호)."},{"기호":"ㄹ","판정":"옳음","설명":"1회성 중개와 보수 수령만으로는 '업'이 되지 않는다는 판례와 같다. 중개업은 업으로 하는 중개다(제2조제3호)."}],"개념":[{"종류":"표","제목":"중개업 관련 용어 정의","머리":["용어","정의의 핵심","조문"],"행":[["중개","중개대상물에 대한 매매·교환·임대차 등 권리 득실변경 행위의 알선","제2조제1호"],["공인중개사","공인중개사자격을 취득한 자(개설등록 여부 무관)","제2조제2호"],["중개업","다른 사람의 의뢰, 일정한 보수, 업으로 중개","제2조제3호"],["개업공인중개사","중개사무소 개설등록을 한 자(자격증 소지 여부는 요건이 아님)","제2조제4호"],["소속공인중개사","개업공인중개사 소속 공인중개사. 법인의 사원·임원인 공인중개사 포함. 중개업무 수행 또는 보조","제2조제5호"],["중개보조원","공인중개사 아닌 자로서 현장안내·일반서무 등 단순 업무 보조","제2조제6호"]]},{"종류":"비교","제목":"소속공인중개사와 중개보조원","왼쪽":{"이름":"소속공인중개사","항목":["공인중개사 자격 있음","중개업무 수행 또는 보조","법인 개업공인중개사의 사원·임원인 공인중개사 포함","확인·설명서에 중개행위를 한 경우 서명 및 날인(제25조제4항)"]},"오른쪽":{"이름":"중개보조원","항목":["공인중개사 자격 없음","현장안내·일반서무 등 단순 업무 보조","고용·고용관계 종료 시 개업공인중개사가 등록관청에 신고(제15조제1항)","고용 상한: 개업공인중개사와 소속공인중개사 합산 수의 5배(제15조제3항)"]}}],"함정":"ㄷ을 중개보조원의 일로 보면 제외하게 된다. 공인중개사가 중개업무를 보조해도 소속공인중개사이고, 중개보조원은 공인중개사가 아닌 자만 해당한다. ㄹ은 보수를 받았다는 사실만 보고 업이라 판단하기 쉽다."},"27회-2차-029":{"한줄":"매매 중개보수는 6천만원의 0.5%인 300,000원이고 임대차는 환산 거래금액 3천6백만원의 0.5%인 180,000원이어서 차이는 120,000원이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제20조제5항제1호","원문":"임대차 중 보증금 외에 차임이 있는 경우에는 월 단위의 차임액에 100을 곱한 금액을 보증금에 합산한 금액을 거래금액으로 한다. 다만, 본문의 규정에 따라 합산한 금액이 5천만원 미만인 경우에는 본문의 규정에 불구하고 월 단위의 차임액에 70을 곱한 금액과 보증금을 합산한 금액을 거래금액으로 한다."},{"법령":"공인중개사법 시행규칙","조문":"제20조제1항","원문":"법 제32조제4항에 따른 주택의 중개에 대한 보수는 중개의뢰인 쌍방으로부터 각각 받되, 그 일방으로부터 받을 수 있는 한도는 별표 1과 같으며, 그 금액은 법 제32조제4항에 따라 시ㆍ도의 조례로 정하는 요율한도 이내에서 중개의뢰인과 개업공인중개사가 서로 협의하여 결정한다."},{"법령":"공인중개사법 시행규칙","조문":"별표 1","원문":"5천만원 이상 2억원 미만 1천분의 5 80만원"},{"법령":"공인중개사법 시행규칙","조문":"별표 1","원문":"2. 임대차 등 5천만원 미만 1천분의 5 20만원"}],"선지":[{"번호":1,"판정":"-","설명":"두 보수가 같다고 볼 때의 값이다. 매매는 300,000원, 임대차는 180,000원이라 같지 않다."},{"번호":2,"판정":"-","설명":"임대차를 월 차임 × 100 으로 환산한 4천5백만원을 거래금액으로 잡으면 225,000원이 나와 차이가 75,000원이 된다. 합산액이 5천만원 미만이면 70을 곱한다(규칙 제20조제5항제1호 단서)."},{"번호":3,"판정":"-","설명":"300,000원 - 180,000원 = 120,000원이다. 정답이다."},{"번호":4,"판정":"-","설명":"임대차 중개보수 180,000원 자체이고 차이가 아니다."},{"번호":5,"판정":"-","설명":"월 차임 × 100 으로 환산한 임대차 보수 225,000원 자체이고 차이가 아니다."}],"개념":[{"종류":"계산","제목":"매매와 임대차 중개보수 차이","단계":[{"설명":"매매 보수 = 거래금액 × 상한요율(5천만원 이상 2억원 미만 1천분의 5, 한도 80만원)","식":"60,000,000 × 0.005","값":"300,000원"},{"설명":"임대차 거래금액 = 보증금 + 월 차임 × 100. 합산액이 5천만원 미만이면 월 차임 × 70","식":"15,000,000 + 300,000 × 100 = 45,000,000 (5천만원 미만이므로 15,000,000 + 300,000 × 70)","값":"36,000,000원"},{"설명":"임대차 보수 = 거래금액 × 상한요율(5천만원 미만 1천분의 5, 한도 20만원)","식":"36,000,000 × 0.005","값":"180,000원"},{"설명":"차이 = 매매 보수 - 임대차 보수","식":"300,000 - 180,000","값":"120,000원"}]},{"종류":"표","제목":"중개보수 거래금액 계산 규칙","머리":["경우","거래금액","조문"],"행":[["임대차에 보증금 외 월 차임이 있음","보증금 + 월 차임 × 100","규칙 제20조제5항제1호"],["위 합산액이 5천만원 미만","보증금 + 월 차임 × 70","규칙 제20조제5항제1호 단서"],["교환계약","교환대상 중개대상물 중 거래금액이 큰 쪽의 가액","규칙 제20조제5항제2호"],["동일 대상물·동일 당사자·동일 기회에 매매를 포함한 둘 이상의 거래","매매계약 거래금액만 적용","규칙 제20조제5항제3호"],["건축물 중 주택 면적이 2분의 1 이상","주택 규정(제1항) 적용","규칙 제20조제6항"],["건축물 중 주택 면적이 2분의 1 미만","주택 외 규정(제4항) 적용","규칙 제20조제6항"]]}],"함정":"월 차임에 100을 곱한 4천5백만원을 그대로 쓰면 임대차 보수가 225,000원이 되고 차이가 75,000원으로 나온다. 합산액이 5천만원 미만이면 70을 곱하는 단서가 걸린다."},"27회-2차-020":{"한줄":"폐업신고 후 1년 이내에 중개사무소 개설등록을 다시 신청하려는 자는 실무교육을 받지 않아도 되므로 ②가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제34조제1항제1호","원문":"폐업신고 후 1년 이내에 중개사무소의 개설등록을 다시 신청 하려는 자"},{"법령":"공인중개사법","조문":"법 제34조제3항","원문":"중개보조원은 제15조제1항에 따른 고용 신고일 전 1년 이내에 시ㆍ도지사 또는 등록관청이 실시하는 직무교육을 받아야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제28조제3항제2호","원문":"교육시간: 12시간 이상 16시간 이하"},{"법령":"공인중개사법 시행령","조문":"영 제28조제4항","원문":"시ㆍ도지사는 법 제34조제4항에 따른 연수교육을 실시하려는 경우 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 연수교육의 일시ㆍ장소ㆍ내용 등을 대상자에게 통지하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"분사무소 책임자는 분사무소 설치 신고일 전 1년 이내에 시·도지사가 실시하는 실무교육을 받아야 한다. 연수교육이 아니다(법 제34조제1항)."},{"번호":2,"판정":"옳음","설명":"폐업신고 후 1년 이내에 개설등록을 다시 신청하려는 자는 실무교육이 면제된다(법 제34조제1항제1호)."},{"번호":3,"판정":"틀림","설명":"연수교육 통지는 실무교육 또는 연수교육을 받은 후 2년이 되기 2개월 전까지 한다(영 제28조제4항). 1개월 전이 아니다."},{"번호":4,"판정":"틀림","설명":"연수교육 시간은 12시간 이상 16시간 이하다(영 제28조제3항제2호). 3시간 이상 4시간 이하는 중개보조원의 직무교육 시간이다(영 제28조제2항제2호)."},{"번호":5,"판정":"틀림","설명":"중개보조원도 고용관계 종료 신고 후 1년 이내에 고용 신고를 다시 하면 직무교육을 받지 않아도 된다(법 제34조제3항 단서)."}],"개념":[{"종류":"표","제목":"개업공인중개사등의 교육","머리":["구분","대상","시기","시간","실시"],"행":[["실무교육","개설등록 신청자(법인은 사원·임원, 분사무소는 책임자), 소속공인중개사","등록신청일·분사무소 신고일·고용 신고일 전 1년 이내","45시간","시·도지사"],["직무교육","중개보조원","고용 신고일 전 1년 이내","3시간 이상 4시간 이하","시·도지사 또는 등록관청"],["연수교육","실무교육을 받은 개업공인중개사·소속공인중개사","실무교육을 받은 후 2년마다","12시간 이상 16시간 이하","시·도지사(2년이 되기 2개월 전까지 일시·장소·내용 통지)"],["부동산거래사고 예방교육","개업공인중개사등","필요하다고 인정할 때","-","국토교통부장관·시·도지사·등록관청(교육일 10일 전까지 공고·통지)"]]},{"종류":"표","제목":"실무교육·직무교육 면제","머리":["대상","면제되는 경우","조문"],"행":[["개설등록 신청자","폐업신고 후 1년 이내에 개설등록을 다시 신청하려는 자","법 제34조제1항제1호"],["개설등록 신청자","소속공인중개사로서 고용관계 종료 신고 후 1년 이내에 개설등록을 신청하려는 자","법 제34조제1항제2호"],["소속공인중개사","고용관계 종료 신고 후 1년 이내에 고용 신고를 다시 하려는 자","법 제34조제2항제1호"],["소속공인중개사","개업공인중개사로서 폐업신고를 한 후 1년 이내에 소속공인중개사로 고용 신고를 하려는 자","법 제34조제2항제2호"],["중개보조원(직무교육)","고용관계 종료 신고 후 1년 이내에 고용 신고를 다시 하려는 자","법 제34조제3항 단서"]]}],"함정":"③은 통지 시기를 1개월 전으로 바꿨고 ④는 직무교육 시간을 연수교육에 붙였다. ⑤는 1년 이내 재고용 면제가 소속공인중개사에게만 있는 줄 알면 옳게 보인다. ①은 분사무소 책임자가 받는 교육이 실무교육이라는 점을 놓치기 쉽다.","개정":"실무교육 시간은 영 제28조제1항제2호에서 45시간으로 정해졌다(개정 2025.10.21). 이 문항의 선지는 실무교육 시간을 묻지 않아 정답에는 영향이 없다."},"27회-2차-022":{"한줄":"포상금은 공소제기 또는 기소유예된 건마다 50만원이고 공동 고발은 균등 배분, 중복 신고는 먼저 신고한 자만 받으므로 甲은 A 50만원 + D 25만원 = 75만원, 乙은 C 50만원 + D 25만원 + E 50만원 = 125만원이다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제36조의2제1항","원문":"법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제2항","원문":"제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제3항","원문":"등록관청은 하나의 사건에 대하여 2인 이상이 공동으로 신고 또는 고발한 경우에는 영 제36조의2제1항에 따른 포상금을 균등하게 배분하여 지급한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제4항","원문":"등록관청은 하나의 사건에 대하여 2건 이상의 신고 또는 고발이 접수된 경우에는 최초로 신고 또는 고발한 자에게 포상금을 지급한다."},{"법령":"공인중개사법","조문":"법 제46조제1항제2호","원문":"거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자"},{"법령":"공인중개사법","조문":"법 제46조제1항제3호","원문":"중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자"}],"선지":[{"번호":1,"판정":"-","설명":"甲 75만원, 乙 50만원. 甲은 맞지만 乙이 C 50만원만 받는 것으로 계산해 D 몫 25만원과 E 50만원이 빠졌다."},{"번호":2,"판정":"-","설명":"甲 75만원, 乙 75만원. 乙이 C 50만원과 D 몫 25만원은 받지만 먼저 신고한 E 건 50만원이 빠졌다."},{"번호":3,"판정":"-","설명":"甲 75만원(A 50 + D 25), 乙 125만원(C 50 + D 25 + E 50). 사건별 지급 여부와 배분이 모두 맞는다."},{"번호":4,"판정":"-","설명":"甲 125만원, 乙 75만원. E 건을 甲이 받는 것으로 본 계산이다. E는 乙이 먼저 신고했으므로 乙만 받는다(시행규칙 제28조제4항)."},{"번호":5,"판정":"-","설명":"甲 125만원, 乙 125만원. B의 무혐의 처분 건을 甲에게 50만원으로 넣은 계산이다. 무혐의는 공소제기도 기소유예도 아니라 지급 대상이 아니다(영 제36조의2제2항)."}],"개념":[{"종류":"계산","제목":"甲·乙 포상금 합계","단계":[{"설명":"A: 甲 고발, 검사 공소제기. 지급 요건 충족","식":"甲 += 50만원","값":"甲 50"},{"설명":"B: 무혐의 처분이라 공소제기·기소유예가 없음","식":"지급 없음","값":"0"},{"설명":"C: 乙 신고, 공소제기 후 무죄. 공소제기가 있으므로 지급","식":"乙 += 50만원","값":"乙 50"},{"설명":"D: 甲·乙 공동 고발(합의 없음), 기소유예. 균등 배분","식":"50만원 ÷ 2","값":"甲 25, 乙 25"},{"설명":"E: 乙이 먼저 신고, 甲은 나중 신고. 최초 신고자에게만 지급","식":"乙 += 50만원","값":"乙 50"},{"설명":"합계","식":"甲 50 + 25 / 乙 50 + 25 + 50","값":"甲 75만원, 乙 125만원"}]},{"종류":"표","제목":"포상금 지급 요건","머리":["구분","내용","조문"],"행":[["신고·고발 대상","무등록 중개업, 거짓·부정한 방법의 개설등록, 중개사무소등록증·공인중개사자격증의 양도·대여·양수·대여받음, 개업공인중개사가 아닌 자의 중개대상물 표시·광고, 제33조제1항제8호·제9호 행위, 제33조제2항의 업무방해","법 제46조제1항"],["지급 요건","행정기관에 발각되기 전에 등록관청·수사기관에 신고·고발하고, 검사가 공소제기 또는 기소유예 결정을 한 경우","영 제36조의2제2항"],["금액","1건당 50만원","영 제36조의2제1항"],["2인 이상 공동 신고·고발","균등 배분(미리 합의하여 신청하면 합의대로)","시행규칙 제28조제3항"],["2건 이상 접수","최초로 신고·고발한 자에게 지급","시행규칙 제28조제4항"],["국고 보조","지급 비용 중 100분의 50 이내","영 제36조의2제3항"]]}],"함정":"재판에서 무죄가 나온 C도 검사의 공소제기가 있었으므로 포상금 대상이다. 무혐의 처분된 B는 공소제기도 기소유예도 없어 제외된다. D는 기소유예도 지급 사유이며 합의가 없으면 균등 배분한다. E는 먼저 신고한 乙에게만 간다."},"27회-2차-021":{"한줄":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고해야 하므로 ㄱ은 옳고, 지회 설치 신고처, 운영위원 임기, 금융기관 임원의 위원 자격에 관한 ㄴ, ㄷ, ㄹ은 틀린다.","근거":[{"법령":"공인중개사법","조문":"법 제41조의2제3항","원문":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다. 이 경우 다음 각 호의 사항은 총회의 의결을 거쳐야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제32조제1항","원문":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제32조제2항","원문":"협회가 그 시ㆍ도회 또는 지회를 설치할 때에는 그 시ㆍ도회는 시ㆍ도지사에게, 지회는 등록관청에 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제35조의2제3항","원문":"제2항제3호 및 제4호에 따른 위원의 임기는 2년으로 하되 1회에 한하여 연임할 수 있으며, 보궐위원의 임기는 전임자 임기의 남은 기간으로 한다."},{"법령":"공인중개사법 시행령","조문":"영 제35조의2제2항제4호다목","원문":"금융감독원 또는 금융기관에서 임원 이상의 직에 있거나 있었던 사람"}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 옳은 보기여서 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄷ이 틀린 보기라 ㄱ, ㄷ 조합은 맞지 않는다."},{"번호":3,"판정":"틀림","설명":"ㄴ, ㄹ이 모두 틀린 보기다."},{"번호":4,"판정":"틀림","설명":"ㄷ, ㄹ이 틀린 보기라 이 조합은 맞지 않다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ, ㄹ이 모두 틀린 보기이고 옳은 ㄱ이 빠졌다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"협회는 총회의 의결내용을 지체 없이 국토교통부장관에게 보고한다(법 제41조의2제3항, 영 제32조제1항)."},{"기호":"ㄴ","판정":"틀림","설명":"협회가 시·도회를 설치하면 시·도지사에게, 지회를 설치하면 등록관청에 신고한다(영 제32조제2항). 지회를 시·도지사에게 신고하는 것이 아니다."},{"기호":"ㄷ","판정":"틀림","설명":"운영위원회 위원의 임기는 2년이고 1회에 한하여 연임할 수 있다(영 제35조의2제3항)."},{"기호":"ㄹ","판정":"틀림","설명":"금융감독원 또는 금융기관에서 임원 이상의 직에 있거나 있었던 사람은 운영위원회 위원으로 위촉될 수 있다(영 제35조의2제2항제4호다목)."}],"개념":[{"종류":"표","제목":"한국공인중개사협회의 설립·조직·보고","머리":["구분","내용","조문"],"행":[["설립","법률에 따라 협회를 설립하고, 협회는 법인","법 제41조제1항·제2항"],["정관","제정·변경 시 국토교통부장관의 인가","법 제41조제2항"],["조직","주사무소에 중앙회, 시·도에 시·도회, 시·군·구에 지회를 둘 수 있음","법 제41조제4항"],["조직 설치 신고","시·도회는 시·도지사에게, 지회는 등록관청에 신고","영 제32조제2항"],["총회","의결내용을 지체 없이 국토교통부장관에게 보고","법 제41조의2제3항, 영 제32조제1항"],["공제사업","비영리사업으로서 회원 간 상호부조를 목적으로 함","영 제31조제6호"],["민법 준용","법에 규정이 없으면 민법 중 사단법인 규정 적용","법 제43조"]]},{"종류":"표","제목":"공제사업 운영위원회","머리":["항목","내용","조문"],"행":[["기능","공제사업에 관한 사항을 심의하고 업무집행을 감독","법 제42조의2제1항"],["위원 수","19명 이내","법 제42조의2제2항"],["구성","국토교통부장관이 지명한 소속 공무원 1명, 협회 회장, 협회 이사회가 임원 중에서 선임한 사람, 협회 회장이 추천해 국토교통부장관 승인으로 위촉하는 사람(부동산·법률·회계·금융·보험 분야 교수·연구원, 변호사·공인회계사·공인중개사 자격자, 금융기관 임원 경력자, 공제조합 업무 5년 이상 종사자, 소비자단체 임원). 성별을 고려","영 제35조의2제2항"],["협회 측 위원 한도","협회 회장과 이사회 선임 임원은 전체 위원 수의 3분의 1 미만","영 제35조의2제2항"],["임기","위촉·선임 위원 2년, 1회 연임 가능","영 제35조의2제3항"],["위원장·부위원장","위원 중에서 각각 호선","영 제35조의2제4항"],["의결","재적위원 과반수 출석, 출석위원 과반수 찬성","영 제35조의2제7항"]]}],"함정":"ㄷ은 임원 임기 감각으로 연임 불가라고 보기 쉽다. 운영위원 임기는 2년이고 1회 연임할 수 있다. ㄹ은 금융기관 임원 경력자가 오히려 위촉 대상(영 제35조의2제2항제4호다목)이라는 점을 놓치면 옳게 보인다.","개정":"협회 명칭이 한국공인중개사협회로 법정화되었다(법 제41조제1항, 개정 2026.2.27). 시·도회는 시·도지사에게, 지회는 등록관청에 신고한다(영 제32조제2항, 개정 2026.8.18). 협회 설립인가·창립총회에 관한 법 제41조제3항은 삭제되었다(2026.2.27)."},"27회-2차-023":{"한줄":"거래계약서에 서명 및 날인을 하지 않은 경우는 법 제36조제1항제5호의 자격정지 사유이므로 ①이 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다."},{"법령":"공인중개사법","조문":"법 제36조제1항제5호","원문":"제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제39조제1항제6호","원문":"제25조제3항의 규정을 위반하여 중개대상물확인ㆍ설명서를 교부하지 아니하거나 보존하지 아니한 경우"},{"법령":"공인중개사법","조문":"법 제39조제1항제3호","원문":"제23조제2항의 규정을 위반하여 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결하거나 계약서를 보존하지 아니한 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제22조제2항","원문":"시ㆍ도지사는 위반행위의 동기ㆍ결과 및 횟수 등을 참작하여 제1항의 규정에 따른 자격정지기간의 2분의 1의 범위 안에서 가중 또는 감경할 수 있다. 이 경우 가중하여 처분하는 때에도 자격정지기간은 6월을 초과할 수 없다."}],"선지":[{"번호":1,"판정":"옳음","설명":"거래계약서 서명·날인 위반은 자격정지 사유다(법 제36조제1항제5호, 시행규칙 별표 3의 정지 기준 3개월)."},{"번호":2,"판정":"틀림","설명":"확인·설명서를 교부하지 않은 경우는 개업공인중개사의 업무정지 사유다(법 제39조제1항제6호). 법 제36조제1항의 자격정지 사유에는 없다."},{"번호":3,"판정":"틀림","설명":"전속중개계약서에 의하지 않은 전속중개계약 체결은 개업공인중개사의 업무정지 사유다(법 제39조제1항제3호). 자격정지 사유가 아니다."},{"번호":4,"판정":"틀림","설명":"자격정지는 시·도지사가 6개월의 범위에서 정한다(법 제36조제1항). 시장·군수·구청장이 아니다."},{"번호":5,"판정":"틀림","설명":"자격정지기간은 2분의 1 범위에서 가중·감경할 수 있지만 가중하더라도 6월을 초과할 수 없다(시행규칙 제22조제2항). 9개월은 불가능하다."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 사유와 기준(법 제36조제1항, 시행규칙 별표 3)","머리":["호","사유","자격정지 기준"],"행":[["1","둘 이상의 중개사무소에 소속된 경우","6개월"],["2","인장등록을 하지 않거나 등록하지 않은 인장을 사용한 경우","3개월"],["3","중개대상물의 확인·설명을 성실·정확하게 하지 않거나 설명의 근거자료를 제시하지 않은 경우","3개월"],["4","중개대상물확인·설명서에 서명 및 날인을 하지 않은 경우","3개월"],["5","거래계약서에 서명 및 날인을 하지 않은 경우","3개월"],["6","거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우","6개월"],["7","제33조제1항 각 호의 금지행위를 한 경우","6개월"]]},{"종류":"비교","제목":"소속공인중개사 자격정지와 개업공인중개사 업무정지","왼쪽":{"이름":"자격정지(법 제36조)","항목":["처분권자: 시·도지사","기간: 6개월의 범위","대상: 소속공인중개사로서 업무를 수행하는 기간 중의 행위","기준: 시행규칙 별표 3, 2분의 1 범위에서 가중·감경(제22조제2항)","가중해도 6월 초과 불가"]},"오른쪽":{"이름":"업무정지(법 제39조)","항목":["처분권자: 등록관청","기간: 6개월의 범위","대상: 개업공인중개사","기준: 시행규칙 별표 4, 2분의 1 범위에서 줄이거나 늘릴 수 있음","사유 발생일부터 3년이 지나면 처분 불가(제39조제3항)"]}}],"함정":"확인·설명서 교부 위반(②)과 전속중개계약서 위반(③)은 개업공인중개사의 업무정지 사유일 뿐 소속공인중개사의 자격정지 사유가 아니다. 서명·날인 위반만 두 제재에 모두 걸린다. ④는 처분권자를 등록관청 개념으로 바꿔 놓았고 ⑤는 가중 상한 6월을 넘겼다."},"27회-2차-024":{"한줄":"최근 1년 이내 업무정지처분을 2회 받고 다시 업무정지에 해당하는 행위를 한 ㄱ, ㄷ은 법 제38조제1항제8호에 따라 반드시 등록을 취소하고, ㄴ, ㄹ은 제2항제10호의 임의적 취소라 ②가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제1항제8호","원문":"최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제2항제10호","원문":"최근 1년 이내에 이 법에 의하여 3회 이상 업무정지 또는 과태료의 처분을 받고 다시 업무정지 또는 과태료의 처분에 해당하는 행위를 한 경우(제1항제8호에 해당하는 경우는 제외한다)"},{"법령":"공인중개사법","조문":"법 제38조제1항","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다."},{"법령":"공인중개사법","조문":"법 제38조제2항","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ도 필요적 취소 사유라 ㄱ만 고른 조합은 부족하다."},{"번호":2,"판정":"옳음","설명":"ㄱ, ㄷ이 필요적 취소 사유이고 ㄴ, ㄹ은 아니어서 이 조합이 맞다."},{"번호":3,"판정":"틀림","설명":"ㄴ, ㄹ은 임의적 취소 사유(제2항제10호)다."},{"번호":4,"판정":"틀림","설명":"ㄹ은 임의적 취소 사유이고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 임의적 취소 사유(제2항제10호)다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"업무정지처분 2회 후 다시 업무정지 해당 행위를 하면 등록을 취소해야 한다(법 제38조제1항제8호)."},{"기호":"ㄴ","판정":"틀림","설명":"업무정지 1회와 과태료 2회는 처분 3회 이상에 해당하지만 업무정지 2회 이상이 아니다. 제2항제10호에 따라 취소할 수 있을 뿐이다."},{"기호":"ㄷ","판정":"옳음","설명":"업무정지처분이 2회이므로 과태료 1회가 더 있어도 제1항제8호에 해당해 취소해야 한다."},{"기호":"ㄹ","판정":"틀림","설명":"과태료 3회 후 업무정지 해당 행위는 제2항제10호에 따라 취소할 수 있는 사유다."}],"개념":[{"종류":"표","제목":"최근 1년 이내 처분 횟수와 제재","머리":["받은 처분","다시 한 행위","제재","조문"],"행":[["업무정지 2회 이상","업무정지 해당 행위","등록취소(필요적)","법 제38조제1항제8호"],["업무정지 또는 과태료 3회 이상(위 경우 제외)","업무정지 또는 과태료 해당 행위","등록취소(임의적)","법 제38조제2항제10호"],["업무정지 또는 과태료 2회 이상","과태료 해당 행위","업무정지(임의적, 6개월)","법 제39조제1항제12호, 시행규칙 별표 4"]]},{"종류":"표","제목":"중개사무소 개설등록 취소 사유","머리":["구분","사유","조문"],"행":[["필요적 취소","개인인 개업공인중개사의 사망, 법인의 해산","법 제38조제1항제1호"],["필요적 취소","거짓이나 그 밖의 부정한 방법으로 개설등록","제1항제2호"],["필요적 취소","결격사유 해당(제10조제1항제2호~제6호, 제11호, 제12호)","제1항제3호"],["필요적 취소","이중등록","제1항제4호"],["필요적 취소","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우","제1항제5호"],["필요적 취소","중개보조원 고용 상한(개업공인중개사와 소속공인중개사 합산 수의 5배) 초과","제1항제5호의2"],["필요적 취소","자기의 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여","제1항제6호"],["필요적 취소","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함","제1항제7호"],["필요적 취소","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위","제1항제8호"],["임의적 취소","등록기준 미달, 둘 이상의 중개사무소, 임시 중개시설물, 겸업 위반","법 제38조제2항제1호~제4호"],["임의적 취소","6개월 초과 휴업, 정보 비공개 위반, 거래계약서 거짓 기재, 손해배상 보장조치 미이행, 금지행위","제2항제5호~제9호"],["임의적 취소","최근 1년 이내 3회 이상 업무정지 또는 과태료 처분을 받고 다시 업무정지 또는 과태료 처분 해당 행위(제1항제8호 해당 제외)","제2항제10호"],["임의적 취소","사업자단체 또는 구성원이 공정거래법 위반으로 최근 2년 이내 2회 이상 처분","제2항제11호"]]}],"함정":"업무정지 횟수가 2회인지가 갈림길이다. 업무정지 1회와 과태료 2회, 과태료 3회는 처분이 합쳐 3회 이상이어도 제2항제10호라서 취소할 수 있을 뿐 취소해야 하는 것은 아니다. ㄷ의 과태료 1회는 결과에 영향이 없다."},"27회-2차-026":{"한줄":"자격정지처분을 받고 그 기간 중에 다른 개업공인중개사의 소속공인중개사가 된 경우는 법 제35조제1항제3호의 자격취소 사유이므로 ⑤가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제35조제1항제3호","원문":"제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제21조","원문":"법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제29조제2항","원문":"자격증을 교부한 시ㆍ도지사와 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 서로 다른 경우에는 공인중개사 사무소의 소재지를 관할하는 시ㆍ도지사가 자격취소처분 또는 자격정지처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시ㆍ도지사에게 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제29조제3항","원문":"시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법","조문":"법 제49조제1항제1호","원문":"제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증은 자격증을 교부한 시·도지사에게 반납한다(시행규칙 제21조). 사무소 소재지 시·도지사가 아니다."},{"번호":2,"판정":"틀림","설명":"부정한 방법으로 자격을 취득한 경우는 자격취소 사유이지만(법 제35조제1항제1호) 법 제49조제1항의 1년 이하 징역 또는 1천만원 이하 벌금 대상에는 들어 있지 않다."},{"번호":3,"판정":"틀림","설명":"자격취소처분을 한 때에는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보한다(영 제29조제3항). 7일이 아니다."},{"번호":4,"판정":"틀림","설명":"두 시·도지사가 다르면 사무소 소재지 시·도지사가 처분에 필요한 절차를 모두 이행한 후 자격증을 교부한 시·도지사에게 통보한다(영 제29조제2항)."},{"번호":5,"판정":"옳음","설명":"자격정지 기간 중 다른 개업공인중개사의 소속공인중개사가 되는 것도 중개업무를 행한 것으로 보아 자격취소 사유다(법 제35조제1항제3호)."}],"개념":[{"종류":"표","제목":"공인중개사 자격취소 사유(법 제35조제1항)","머리":["호","사유"],"행":[["1","부정한 방법으로 공인중개사의 자격을 취득한 경우"],["2","다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도·대여한 경우"],["3","자격정지처분을 받고 그 정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인인 개업공인중개사의 사원·임원이 되는 경우 포함)"],["4","이 법 또는 공인중개사의 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우"]]},{"종류":"흐름","제목":"자격취소 절차","단계":[{"이름":"청문","설명":"시·도지사가 자격을 취소하려면 청문을 실시(법 제35조제2항)"},{"이름":"처분","설명":"자격증을 교부한 시·도지사가 처분. 사무소 소재지 시·도지사와 다르면 사무소 소재지 시·도지사가 절차를 모두 이행한 후 교부한 시·도지사에게 통보(영 제29조제1항·제2항)"},{"이름":"통보","설명":"취소처분을 한 때 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보(영 제29조제3항)"},{"이름":"반납","설명":"처분을 받은 날부터 7일 이내에 자격증을 교부한 시·도지사에게 반납. 분실 등이면 사유서 제출(시행규칙 제21조, 법 제35조제4항)"},{"이름":"미반납 제재","설명":"반납·사유서 제출 의무 위반 시 100만원 이하 과태료(법 제51조제3항제6호), 시·도지사가 부과"}]}],"함정":"③의 7일은 자격증 반납 기한(7일)과 통보 기한(5일)을 섞은 것이다. ④는 절차를 이행하는 시·도지사가 반대로 적혀 있다. ②는 자격취소 사유라고 해서 곧바로 형벌이 따른다고 보면 속는다.","개정":"시·도지사의 자격취소 통보는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보하는 것으로 정해져 있다(영 제29조제3항, 개정 2023.11.16). ③은 문구를 현행 통보로 맞춰 실었으나 7일이라는 기한이 맞지 않아 여전히 틀린 선지다."},"27회-2차-018":{"한줄":"중개의뢰인과 직접 거래를 하는 행위(제33조제1항제6호)는 제48조제3호에 따라 3년 이하 징역 또는 3천만원 이하 벌금 대상이어서 1년 이하 징역 또는 1천만원 이하 벌금 사유가 아니므로 ④가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제48조제3호","원문":"제33조제1항제5호부터 제9호까지의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"법 제33조제1항제6호","원문":"중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"법 제49조제1항제1호","원문":"제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자"},{"법령":"공인중개사법","조문":"법 제49조제1항제7호","원문":"제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자"},{"법령":"공인중개사법","조문":"법 제49조제1항제3호","원문":"제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자"},{"법령":"공인중개사법","조문":"법 제49조제1항제5호","원문":"제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"공인중개사자격증 대여는 1년 이하 징역 또는 1천만원 이하 벌금 사유다(법 제49조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"중개사무소등록증 양도는 1년 이하 징역 또는 1천만원 이하 벌금 사유다(법 제49조제1항제7호)."},{"번호":3,"판정":"옳음","설명":"이중으로 개설등록을 하는 것은 1년 이하 징역 또는 1천만원 이하 벌금 사유다(법 제49조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"중개의뢰인과의 직접 거래는 제33조제1항제6호로서 3년 이하 징역 또는 3천만원 이하 벌금 사유다(법 제48조제3호)."},{"번호":5,"판정":"옳음","설명":"임시 중개시설물 설치는 1년 이하 징역 또는 1천만원 이하 벌금 사유다(법 제49조제1항제5호)."}],"개념":[{"종류":"표","제목":"벌칙 정리(법 제48조·제49조)","머리":["형량","행위","조문"],"행":[["3년 이하 징역 또는 3천만원 이하 벌금","무등록 중개업, 거짓·부정한 방법의 개설등록","법 제48조제1호·제2호"],["3년 이하 징역 또는 3천만원 이하 벌금","제33조제1항제5호~제9호 금지행위(증서 등 중개, 직접 거래·쌍방 대리, 투기 조장, 시세 부당 영향, 단체 중개 제한)","법 제48조제3호"],["3년 이하 징역 또는 3천만원 이하 벌금","제33조제2항의 업무방해","법 제48조제4호"],["1년 이하 징역 또는 1천만원 이하 벌금","자격증 양도·대여·양수 및 성명 사용 허락, 그 알선","법 제49조제1항제1호·제1호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","개업공인중개사 등록증 양도·대여, 성명·상호 사용 허락, 그 알선","법 제49조제1항제7호·제7호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","이중등록·이중소속, 둘 이상의 중개사무소, 임시 중개시설물, 중개보조원 고용 상한 초과","법 제49조제1항제3호~제5호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","공인중개사·공인중개사사무소·부동산중개 유사명칭 사용, 개업공인중개사가 아닌 자의 중개대상물 표시·광고","법 제49조제1항제2호·제6호·제6호의2"],["1년 이하 징역 또는 1천만원 이하 벌금","거래정보사업자의 의뢰받지 않은 정보 공개, 업무상 비밀누설(피해자 의사에 반하여 벌하지 않음)","법 제49조제1항제8호·제9호, 제2항"],["1년 이하 징역 또는 1천만원 이하 벌금","제33조제1항제1호~제4호 금지행위(매매업, 무등록업자와 거래, 보수 초과 수수, 거짓 언행)","법 제49조제1항제10호"]]},{"종류":"비교","제목":"제33조제1항 금지행위의 형량","왼쪽":{"이름":"3년 이하 징역 또는 3천만원 이하 벌금(제48조)","항목":["제5호 양도·알선 금지 부동산의 증서 등 중개","제6호 직접 거래, 쌍방 대리","제7호 투기 조장","제8호 시세에 부당한 영향","제9호 단체 구성 중개 제한"]},"오른쪽":{"이름":"1년 이하 징역 또는 1천만원 이하 벌금(제49조)","항목":["제1호 중개대상물의 매매업","제2호 무등록업자와의 거래·명의 이용","제3호 보수·실비 초과 수수","제4호 거짓된 언행"]}}],"함정":"직접 거래는 금지행위 중에서도 형량이 무거운 쪽(제5호~제9호)에 속한다. 금지행위 아홉 개 호는 제1호~제4호(1년·1천만원)와 제5호~제9호(3년·3천만원)로 나뉜다."},"27회-2차-019":{"한줄":"손해배상책임에 관한 사항을 설명하지 않은 경우의 과태료는 등록관청이 부과·징수하므로 시·도지사라고 한 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제51조제5항제4호","원문":"제2항제1호ㆍ제1호의4ㆍ제1호의6, 제3항제1호ㆍ제2호ㆍ제2호의2, 제3호부터 제5호까지 및 제7호의 경우: 등록관청"},{"법령":"공인중개사법","조문":"법 제51조제5항제1호","원문":"제2항제1호의2ㆍ제1호의3ㆍ제1호의5, 제6호부터 제8호까지, 제8호의2 및 제9호의 경우: 국토교통부장관"},{"법령":"공인중개사법","조문":"법 제51조제5항제2호","원문":"제2항제5호의2 및 제3항제6호의 경우: 시ㆍ도지사"},{"법령":"공인중개사법","조문":"법 제51조제3항제5호","원문":"제30조제5항을 위반하여 손해배상책임에 관한 사항을 설명하지 아니하거나 관계 증서의 사본 또는 관계 증서에 관한 전자문서를 교부하지 아니한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"등록증 게시 위반(제51조제3항제1호)은 등록관청이 부과·징수한다."},{"번호":2,"판정":"옳음","설명":"이전신고 위반(제51조제3항제3호)은 등록관청이 부과·징수한다."},{"번호":3,"판정":"옳음","설명":"사무소 명칭 위반(제51조제3항제2호)은 등록관청이 부과·징수한다."},{"번호":4,"판정":"틀림","설명":"손해배상책임에 관한 사항 설명 위반(제51조제3항제5호)은 등록관청이 부과·징수한다(제51조제5항제4호). 시·도지사가 아니다."},{"번호":5,"판정":"옳음","설명":"부동산거래정보망 운영규정 위반(제51조제2항제1호의5)은 국토교통부장관이 부과·징수한다(제51조제5항제1호)."}],"개념":[{"종류":"표","제목":"과태료 부과·징수권자(법 제51조제5항)","머리":["부과권자","과태료 사유","조문"],"행":[["국토교통부장관","인터넷 광고 모니터링 자료 제출·조치 요구 불이행, 부동산거래정보망 운영규정 위반, 거래정보사업자의 보고·검사 거부, 공제사업 운용실적 미공시, 공제 개선명령 불이행, 임원 징계·해임 요구 불이행, 협회 조사·검사 거부","제2항제1호의2·제1호의3·제1호의5·제6호~제8호·제8호의2·제9호"],["시·도지사","연수교육 미이수, 공인중개사자격증 미반납·사유서 미제출","제2항제5호의2, 제3항제6호"],["등록관청","부당 표시·광고, 중개보조원 신분 미고지, 확인·설명 불성실, 등록증 미게시, 사무소 명칭 위반, 표시·광고 위반, 이전신고·휴업·폐업·재개·휴업기간 변경 미신고, 손해배상책임 설명·증서 교부 위반, 등록증 미반납","제2항제1호·제1호의4·제1호의6, 제3항제1호~제5호·제7호"]]},{"종류":"표","제목":"과태료 금액(영 별표 2)","머리":["위반행위","과태료"],"행":[["공제업무 개선명령 불이행","400만원"],["임원 징계·해임 요구·시정명령 불이행","400만원"],["부동산거래정보망 운영규정 위반","400만원"],["공제사업 운용실적 미공시","300만원"],["확인·설명 불성실 또는 근거자료 미제시","250만원 또는 500만원"],["연수교육 미이수","위반 기간별 20만원~100만원"],["사무소 명칭 위반, 등록증 미반납","50만원"],["등록증 미게시, 이전신고, 손해배상 설명 위반, 자격증 미반납","30만원"],["휴업·폐업·재개·휴업기간 변경 미신고","20만원"]]}],"함정":"시·도지사가 부과하는 과태료는 연수교육 미이수와 자격증 미반납 두 가지뿐이다(제51조제5항제2호). 나머지 중개업무 관련 과태료는 등록관청이고, 거래정보사업자와 협회 관련은 국토교통부장관이다."},"27회-2차-002":{"한줄":"정책심의위원회가 심의한 사항 중 시·도지사가 따라야 하는 것은 제1호(자격취득)뿐이므로 중개보수 변경에 관한 심의에 시·도지사가 따라야 한다고 한 ③이 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제2조의2제3항","원문":"제1항에 따라 공인중개사 정책심의위원회에서 심의한 사항 중 제1호의 경우에는 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 이에 따라야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의2제1항","원문":"「공인중개사법」(이하 \"법\"이라 한다) 제2조의2제1항에 따른 공인중개사 정책심의위원회(이하 \"심의위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의2제2항","원문":"심의위원회 위원장은 국토교통부 제1차관이 되고, 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 국토교통부장관이 임명하거나 위촉한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의3제1항제3호","원문":"위원이 해당 안건에 대하여 증언, 진술, 자문, 조사, 연구, 용역 또는 감정을 한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제1조의4제2항","원문":"위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"위원장은 국토교통부 제1차관이 된다(영 제1조의2제2항)."},{"번호":2,"판정":"옳음","설명":"심의위원회는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다(영 제1조의2제1항)."},{"번호":3,"판정":"틀림","설명":"시·도지사가 따라야 하는 것은 제1호(공인중개사의 시험 등 자격취득)에 관한 심의사항뿐이다(법 제2조의2제3항). 중개보수 변경(제3호)은 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"위원이 해당 안건에 대하여 연구, 용역 또는 감정을 한 경우 심의·의결에서 제척된다(영 제1조의3제1항제3호)."},{"번호":5,"판정":"옳음","설명":"위원장이 직무를 수행할 수 없으면 위원장이 미리 지명한 위원이 직무를 대행한다(영 제1조의4제2항)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]},{"종류":"표","제목":"자격시험·자격증 규정","머리":["항목","내용","조문"],"행":[["시험 시행","시·도지사가 시행. 국토교통부장관이 직접 출제·시행하려면 심의위원회 의결을 미리 거침","법 제4조, 영 제3조"],["시험 미시행","부득이한 사정이 있으면 심의위원회 의결을 거쳐 당해연도 시험을 시행하지 않을 수 있음","영 제7조제1항"],["시행 공고","예정 시험일시·방법 등 개략적 사항을 매년 2월 말일까지 일간신문·관보·방송 중 하나 이상에 공고하고 인터넷 홈페이지에도 공고","영 제7조제2항"],["세부 공고","시험일시·장소·방법 등을 시험시행일 90일 전까지 공고","영 제7조제3항"],["부정행위자","시험 무효, 처분일부터 5년간 응시자격 정지","법 제4조의3"],["자격증 교부","시·도지사가 합격자 결정 공고일부터 1개월 이내에 자격증교부대장 기재 후 교부","법 제5조제2항, 시행규칙 제3조제1항"],["자격증 재교부","자격증을 교부한 시·도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["자격 결격","자격취소 후 3년이 지나지 않은 자는 공인중개사가 될 수 없음","법 제6조"],["자격증 대여 등 금지","성명 사용 허락, 자격증 양도·대여, 양수·대여받음, 알선 금지","법 제7조"]]}],"함정":"심의위원회의 심의 범위(네 가지)와 시·도지사를 구속하는 범위(제1호 하나)를 구분하지 못하면 ③이 옳게 보인다. 중개보수 변경은 심의사항이지만 시·도지사에게 구속력이 없다."},"27회-2차-003":{"한줄":"시·도지사는 합격자 결정 공고일부터 1개월 이내에 자격증을 교부하므로 2개월 이내라고 한 ①이 틀리다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제3조제1항","원문":"특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 「공인중개사법」(이하 \"법\"이라 한다) 제5조제1항에 따른 시험합격자의 결정 공고일부터 1개월 이내에 시험합격자에 관한 사항을 별지 제2호서식의 공인중개사자격증교부대장에 기재한 후, 시험 합격자에게 별지 제3호서식의 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법","조문":"법 제6조","원문":"제35조제1항에 따라 공인중개사의 자격이 취소된 후 3년이 지나지 아니한 자는 공인중개사가 될 수 없다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"법 제7조제1항","원문":"공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다."},{"판례":"대법원 판례(공인중개사자격증 대여의 의미)","요지":"공인중개사자격증의 대여란 다른 사람이 그 자격증을 이용하여 공인중개사로 행세하면서 공인중개사의 업무를 행하려는 것을 알면서도 그에게 자격증 자체를 빌려주는 것을 말한다."},{"법령":"공인중개사법","조문":"법 제35조제1항제2호","원문":"제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"자격증 교부는 합격자 결정 공고일부터 1개월 이내다(시행규칙 제3조제1항). 2개월이 아니다."},{"번호":2,"판정":"옳음","설명":"자격이 취소된 후 3년이 지나지 않은 자는 공인중개사가 될 수 없다(법 제6조)."},{"번호":3,"판정":"옳음","설명":"재교부신청서는 자격증을 교부한 시·도지사에게 제출한다(시행규칙 제3조제2항)."},{"번호":4,"판정":"옳음","설명":"판례가 말하는 자격증 대여의 의미와 같다. 다른 사람이 공인중개사로 행세하며 업무를 하려는 것을 알면서 자격증 자체를 빌려주는 것이다."},{"번호":5,"판정":"옳음","설명":"자기의 성명을 사용하여 중개업무를 하게 하면 시·도지사는 자격을 취소해야 한다(법 제35조제1항제2호)."}],"개념":[{"종류":"표","제목":"자격시험·자격증 규정","머리":["항목","내용","조문"],"행":[["시험 시행","시·도지사가 시행. 국토교통부장관이 직접 출제·시행하려면 심의위원회 의결을 미리 거침","법 제4조, 영 제3조"],["시험 미시행","부득이한 사정이 있으면 심의위원회 의결을 거쳐 당해연도 시험을 시행하지 않을 수 있음","영 제7조제1항"],["시행 공고","예정 시험일시·방법 등 개략적 사항을 매년 2월 말일까지 일간신문·관보·방송 중 하나 이상에 공고하고 인터넷 홈페이지에도 공고","영 제7조제2항"],["세부 공고","시험일시·장소·방법 등을 시험시행일 90일 전까지 공고","영 제7조제3항"],["부정행위자","시험 무효, 처분일부터 5년간 응시자격 정지","법 제4조의3"],["자격증 교부","시·도지사가 합격자 결정 공고일부터 1개월 이내에 자격증교부대장 기재 후 교부","법 제5조제2항, 시행규칙 제3조제1항"],["자격증 재교부","자격증을 교부한 시·도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["자격 결격","자격취소 후 3년이 지나지 않은 자는 공인중개사가 될 수 없음","법 제6조"],["자격증 대여 등 금지","성명 사용 허락, 자격증 양도·대여, 양수·대여받음, 알선 금지","법 제7조"]]},{"종류":"표","제목":"공인중개사 자격취소 사유(법 제35조제1항)","머리":["호","사유"],"행":[["1","부정한 방법으로 공인중개사의 자격을 취득한 경우"],["2","다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도·대여한 경우"],["3","자격정지처분을 받고 그 정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인인 개업공인중개사의 사원·임원이 되는 경우 포함)"],["4","이 법 또는 공인중개사의 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우"]]}],"함정":"교부 기한은 1개월이다. 2개월은 다른 제도의 기한과 섞은 숫자다. 재교부와 자격증 교부 모두 시·도지사 사무라는 점도 함께 정리해 둔다."},"27회-2차-004":{"한줄":"상법상 회사로서 자본금이 5천만원 이상이면 법인의 등록기준에 맞는다(영 제13조제1항제2호가목).","근거":[{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호가목","원문":"가. 「상법」상 회사 또는 「협동조합 기본법」 제2조제1호에 따른 협동조합(같은 조 제3호에 따른 사회적협동조합은 제외한다)으로서 자본금이 5천만원 이상일 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호다목","원문":"다. 대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호라목","원문":"라. 대표자, 임원 또는 사원 전원 및 분사무소의 책임자(법 제13조제3항에 따라 분사무소를 설치하려는 경우에만 해당한다)가 법 제34조제1항에 따른 실무교육을 받았을 것"},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호마목","원문":"마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"},{"법령":"공인중개사법","조문":"법 제34조의2제2항","원문":"국토교통부장관, 시ㆍ도지사 및 등록관청은 필요하다고 인정하면 대통령령으로 정하는 바에 따라 개업공인중개사등의 부동산거래사고 예방을 위한 교육을 실시할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"중개사무소의 면적 기준은 없다. 건축물대장에 기재된 건물에 소유·전세·임대차·사용대차 등으로 사용권을 확보하면 된다(영 제13조제1항제2호마목)."},{"번호":2,"판정":"틀림","설명":"법인은 대표자, 임원 또는 사원 전원이 실무교육을 받아야 한다(영 제13조제1항제2호라목). 부동산거래사고 예방교육은 등록기준에 없다(법 제34조의2제2항은 실시할 수 있다는 규정)."},{"번호":3,"판정":"틀림","설명":"협동조합 중 사회적협동조합은 법인의 자본금 요건에서 제외된다(영 제13조제1항제2호가목)."},{"번호":4,"판정":"옳음","설명":"상법상 회사는 자본금이 5천만원 이상이어야 한다(영 제13조제1항제2호가목)."},{"번호":5,"판정":"틀림","설명":"대표자는 공인중개사여야 하고, 대표자를 제외한 임원 또는 사원의 3분의 1 이상이 공인중개사여야 한다(영 제13조제1항제2호다목)."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 기준(영 제13조제1항)","머리":["구분","공인중개사","법인"],"행":[["자본금","요건 없음","상법상 회사 또는 협동조합(사회적협동조합 제외)으로서 5천만원 이상"],["업무 범위","-","법 제14조에 규정된 업무만 영위할 목적으로 설립"],["공인중개사 요건","본인이 공인중개사","대표자는 공인중개사, 대표자를 제외한 임원·사원의 3분의 1 이상이 공인중개사"],["실무교육","본인","대표자·임원·사원 전원, 분사무소를 설치하려면 분사무소 책임자도 포함"],["사무소","건축물대장에 기재된 건물에 소유·전세·임대차·사용대차 등으로 사용권 확보","같음"],["예외","-","다른 법률에 따라 중개업을 할 수 있는 경우 위 기준을 적용하지 않음"]]},{"종류":"표","제목":"교육의 종류와 대상(법 제34조, 영 제28조)","머리":["교육","대상","시기","시간"],"행":[["실무교육","개설등록 신청자(법인은 사원·임원, 분사무소는 책임자), 소속공인중개사","등록신청일(분사무소 설치신고일, 고용 신고일) 전 1년 이내","45시간"],["직무교육","중개보조원","고용 신고일 전 1년 이내","3시간 이상 4시간 이하"],["연수교육","실무교육을 받은 개업공인중개사·소속공인중개사","실무교육 후 2년마다","12시간 이상 16시간 이하"],["면제","폐업신고·고용관계 종료 신고 후 1년 이내 재신청·재신고하는 자","법 제34조제1항·제2항·제3항 단서","-"]]}],"함정":"면적 기준은 없다(①). 교육은 부동산거래사고 예방교육이 아니라 실무교육이다(②). 협동조합은 되지만 사회적협동조합은 제외다(③). 공인중개사 비율은 대표자를 제외한 임원·사원의 3분의 1이다(⑤)."},"27회-2차-005":{"한줄":"실형의 집행이 끝난 날부터 2년이 지났을 뿐이면 3년에 못 미쳐 결격이므로 ②가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제10조제1항제4호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 실형의 선고를 받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제5호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 형의 집행유예를 받고 그 유예기간이 만료된 날부터 2년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제38조제1항제4호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다. 제12조제1항의 규정을 위반하여 이중으로 중개사무소의 개설등록을 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제1호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제14조제1호","원문":"등록관청은 다음 각 호의 어느 하나에 해당하는 때에는 그 사실을 국토교통부령이 정하는 바에 따라 법 제41조에 따른 한국공인중개사협회에 통보해야 한다. 법 제11조제1항의 규정에 따라 중개사무소등록증을 교부한 때"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제6조","원문":"등록관청은 영 제14조의 규정에 따라 매월 중개사무소의 등록ㆍ행정처분 및 신고 등에 관한 사항을 별지 제8호서식의 중개사무소등록ㆍ행정처분등통지서에 기재하여 다음달 10일까지 한국공인중개사협회에 통보해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"집행유예는 유예기간이 만료된 날부터 2년이 지나야 결격이 풀린다. 만료 후 2년이 지났으면 등록할 수 있다(법 제10조제1항제5호)."},{"번호":2,"판정":"틀림","설명":"금고 이상의 실형은 집행이 종료되거나 면제된 날부터 3년이 지나야 한다. 2년 경과는 결격이다(법 제10조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"이중으로 개설등록을 하면 등록관청은 개설등록을 취소해야 한다(법 제38조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"개업공인중개사인 법인이 해산하면 등록관청은 개설등록을 취소해야 한다(법 제38조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"등록증을 교부한 때에는 매월 그 사항을 다음달 10일까지 한국공인중개사협회에 통보한다(영 제14조제1호, 시행규칙 제6조)."}],"개념":[{"종류":"표","제목":"결격 기간 비교(법 제10조제1항)","머리":["사유","기산 시점","기간"],"행":[["금고 이상의 실형(제4호)","집행 종료·집행 면제일","3년"],["금고 이상의 집행유예(제5호)","유예기간 만료일","2년(유예기간 중 포함)"],["이 법 위반 300만원 이상 벌금형(제11호)","선고일","3년"],["공인중개사 자격취소(제6호)","취소일","3년"],["개설등록 취소(제8호)","취소일","3년(법 제40조제3항 취소는 폐업기간 공제)"],["자격정지(제7호)","-","자격정지기간 중"],["업무정지 후 폐업(제9호)","-","업무정지기간이 지나기 전"]]},{"종류":"표","제목":"등록관청이 반드시 등록을 취소하는 경우(법 제38조제1항)","머리":["호","사유"],"행":[["1","개인인 개업공인중개사의 사망, 개업공인중개사인 법인의 해산"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록"],["3","제10조제1항제2호~제6호, 제11호·제12호의 결격사유에 해당하게 된 경우(제12호는 사유 발생일부터 2개월 이내 해소하면 제외)"],["4","이중으로 개설등록"],["5","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우"],["5의2","개업공인중개사와 소속공인중개사를 합한 수의 5배를 넘겨 중개보조원 고용"],["6","성명·상호 사용 중개업무를 하게 하거나 등록증을 양도·대여"],["7","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 한 경우"],["8","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위"]]}],"함정":"실형은 집행 종료·면제일부터 3년, 집행유예는 유예기간 만료일부터 2년으로 기간이 다르다. ②의 2년은 집행유예 기준에는 맞아도 실형 기준에는 모자란다.","개정":"집행유예 결격은 법 제10조제1항제5호의 2023.4.18 개정으로 \"유예기간 중\"에서 \"유예기간이 만료된 날부터 2년이 지나지 아니한 자\"로 넓어졌다. ①은 이에 맞춰 \"유예기간이 만료된 날부터 2년이 경과된\"으로 고쳐 실었다. 협회 명칭은 \"한국공인중개사협회\"로 정비되어(법 제41조제1항 개정 2026.2.27, 영 제14조 개정 2026.8.18, 시행규칙 제6조 개정 2026.8.11) ⑤도 현행 명칭으로 실었다."},"27회-2차-006":{"한줄":"이중등록(ㄱ, ㄴ), 중개보조원의 이중소속 금지(ㄷ), 이중소속의 벌칙(ㄹ)이 모두 법 제12조·제49조에 맞다.","근거":[{"법령":"공인중개사법","조문":"법 제12조","원문":"①개업공인중개사는 이중으로 중개사무소의 개설등록을 하여 중개업을 할 수 없다. ②개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"법 제10조제3항","원문":"등록관청은 개업공인중개사ㆍ소속공인중개사ㆍ중개보조원 및 개업공인중개사인 법인의 사원ㆍ임원(이하 \"개업공인중개사등\"이라 한다)이 제1항제1호부터 제11호까지의 어느 하나에 해당하는지 여부를 확인하기 위하여 관계 기관에 조회할 수 있다."},{"법령":"공인중개사법","조문":"법 제49조제1항제3호","원문":"다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자"},{"법령":"공인중개사법","조문":"법 제38조제1항제4호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다. 제12조제1항의 규정을 위반하여 이중으로 중개사무소의 개설등록을 한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 옳은 보기라서 ㄱ, ㄴ만 고른 조합은 모자란다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄴ도 옳은 보기라서 ㄷ, ㄹ만 고른 조합은 모자란다."},{"번호":3,"판정":"틀림","설명":"ㄹ도 옳은 보기라서 이 조합은 모자란다."},{"번호":4,"판정":"틀림","설명":"ㄱ도 옳은 보기라서 이 조합은 모자란다."},{"번호":5,"판정":"옳음","설명":"ㄱ, ㄴ, ㄷ, ㄹ이 모두 옳다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"같은 등록관청에서 다시 개설등록을 하는 것도 이중으로 개설등록을 하는 것이다(법 제12조제1항)."},{"기호":"ㄴ","판정":"옳음","설명":"다른 군에 다시 개설등록을 하는 경우도 이중등록이다(법 제12조제1항)."},{"기호":"ㄷ","판정":"옳음","설명":"중개보조원은 개업공인중개사등에 속하므로 다른 개업공인중개사인 법인의 사원·임원이 될 수 없다(법 제12조제2항, 제10조제3항)."},{"기호":"ㄹ","판정":"옳음","설명":"이중소속은 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제3호)."}],"개념":[{"종류":"비교","제목":"이중등록과 이중소속(법 제12조)","왼쪽":{"이름":"이중등록(제1항)","항목":["대상: 개업공인중개사","행위: 이중으로 개설등록을 하여 중개업을 하는 것","등록관청이 같든 다르든 이중으로 등록하면 해당","벌칙: 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제3호)","행정처분: 등록 취소(법 제38조제1항제4호)"]},"오른쪽":{"이름":"이중소속(제2항)","항목":["대상: 개업공인중개사등(개업공인중개사, 소속공인중개사, 중개보조원, 법인의 사원·임원)","행위: 다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 되는 것","벌칙: 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제3호)","개업공인중개사: 등록 취소(법 제38조제1항제5호)","소속공인중개사: 자격정지(법 제36조제1항제1호)"]}},{"종류":"표","제목":"1년 이하의 징역 또는 1천만원 이하의 벌금(법 제49조제1항)","머리":["호","행위"],"행":[["1","자격증 양도·대여, 성명을 사용한 중개업무, 자격증 양수·대여"],["1의2","자격증 대여 등의 알선"],["2","공인중개사가 아닌 자의 공인중개사 유사명칭 사용"],["3","이중등록, 둘 이상의 중개사무소에 소속"],["4","둘 이상의 중개사무소를 둔 자"],["5","임시 중개시설물 설치"],["5의2","중개보조원 5배 초과 고용"],["6","개업공인중개사가 아닌 자의 \"공인중개사사무소\"·\"부동산중개\" 명칭 사용"],["6의2","개업공인중개사가 아닌 자의 중개대상물 표시·광고"],["7·7의2","등록증·성명·상호 대여, 양수, 알선"],["8","거래정보사업자의 의뢰 내용과 다른 정보 공개, 차별적 공개"],["9","업무상 비밀 누설(피해자의 명시한 의사에 반하여 벌하지 않음)"],["10","법 제33조제1항제1호~제4호 금지행위"]]}],"함정":"이중등록은 등록관청이 같은 곳(ㄱ)이든 다른 곳(ㄴ)이든 \"이중으로\" 개설등록을 하면 성립한다. 중개보조원도 개업공인중개사등에 속해 다른 법인의 사원이 될 수 없다(ㄷ). 이중소속의 벌칙은 이중등록과 같은 제49조제1항제3호다(ㄹ)."},"27회-2차-007":{"한줄":"유치권이 행사되고 있어도 건축물은 법 제3조제2호의 중개대상물이다.","근거":[{"법령":"공인중개사법","조문":"법 제3조","원문":"이 법에 의한 중개대상물은 다음 각 호와 같다. 1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법","조문":"법 제40조제4항","원문":"제3항에 따라 행정처분을 하는 경우에는 폐업기간과 폐업의 사유 등을 고려하여야 한다."},{"법령":"공인중개사법","조문":"법 제10조제1항제11호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제12조제2항","원문":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"법 제33조제1항제2호","원문":"개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위"},{"법령":"공인중개사법","조문":"법 제49조제1항제10호","원문":"다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"재등록 개업공인중개사에게 폐업 전 위반행위로 처분할 때는 폐업기간과 폐업의 사유 등을 고려해야 한다(법 제40조제4항)."},{"번호":2,"판정":"틀림","설명":"이 법 위반으로 300만원 이상 벌금형을 선고받고 3년이 지나지 않은 자가 결격이다. 200만원 벌금형은 결격이 아니고 기간도 5년이 아니다(법 제10조제1항제11호)."},{"번호":3,"판정":"틀림","설명":"휴업 중이어도 개업공인중개사는 다른 개업공인중개사인 법인의 사원·임원이 될 수 없다(법 제12조제2항)."},{"번호":4,"판정":"틀림","설명":"무등록 중개업자에게 중개를 의뢰한 거래당사자를 처벌하는 규정은 법 제48조·제49조에 없다. 무등록업자인 줄 알면서 중개를 의뢰받는 쪽은 개업공인중개사등이며 금지행위다(법 제33조제1항제2호, 제49조제1항제10호)."},{"번호":5,"판정":"옳음","설명":"유치권이 행사되고 있는 건물도 건축물이므로 중개대상물이다(법 제3조제2호)."}],"개념":[{"종류":"표","제목":"중개대상물의 범위(법 제3조, 영 제2조)","머리":["구분","대상","근거"],"행":[["토지","지목·용도를 가리지 않는 토지","법 제3조제1호"],["건축물","건축물 그 밖의 토지의 정착물","법 제3조제2호"],["입목","「입목에 관한 법률」에 따른 입목","영 제2조제1호"],["재단","「공장 및 광업재단 저당법」에 따른 공장재단·광업재단","영 제2조제2호"]]},{"종류":"표","제목":"폐업 후 재등록과 행정처분(법 제40조)","머리":["구분","내용"],"행":[["지위 승계","폐업신고 후 다시 개설등록을 하면 폐업신고 전 개업공인중개사의 지위를 승계(제1항)"],["처분효과 승계","업무정지·과태료 등 처분의 효과는 처분일부터 1년간 재등록 개업공인중개사에게 승계(제2항)"],["폐업 전 위반행위 처분","재등록 개업공인중개사에 대해 폐업 전의 제38조·제39조 위반행위로 처분 가능(제3항)"],["처분 제외","폐업기간이 3년을 초과한 경우, 업무정지 사유인데 폐업기간이 1년을 초과한 경우(제3항 각 호)"],["고려사항","처분할 때 폐업기간과 폐업의 사유 등을 고려(제4항)"],["법인 대표자","법인의 대표자에게도 준용(제5항)"]]}],"함정":"④에서 처벌 대상은 무등록 중개업을 한 사람이고, 의뢰한 거래당사자는 처벌 규정이 없다. ②는 300만원과 3년이라는 두 수치가 모두 현행 조문과 다르다. ①은 폐업기간·폐업 사유를 반드시 고려하도록 되어 있다."},"27회-2차-027":{"한줄":"수수료 납부 대상은 분사무소 설치 신고, 개설등록 신청, 등록증 재교부 신청 3가지다.","근거":[{"법령":"공인중개사법","조문":"법 제47조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부하여야 한다. 다만, 공인중개사자격시험을 제4조제2항의 규정에 따라 국토교통부장관이 시행하는 경우 제1호에 해당하는 자는 국토교통부장관이 결정ㆍ공고하는 수수료를 납부하여야 한다. 1. 제4조에 따른 공인중개사자격시험에 응시하는 자 2. 제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자 3. 제9조제1항에 따라 중개사무소의 개설등록을 신청하는 자 4. 제11조제2항에 따라 중개사무소등록증의 재교부를 신청하는 자 5. 제13조제3항에 따라 분사무소설치의 신고를 하는 자 6. 제13조제5항에 따라 분사무소설치신고확인서의 재교부를 신청하는 자"},{"법령":"공인중개사법","조문":"법 제13조제5항","원문":"제5조제3항은 제4항에 따른 신고확인서의 재교부에 관하여 이를 준용한다."},{"법령":"공인중개사법","조문":"법 제11조제2항","원문":"제5조제3항의 규정은 중개사무소등록증의 재교부에 관하여 이를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수수료 납부 대상이 3가지라서 1개가 아니다."},{"번호":2,"판정":"틀림","설명":"수수료 납부 대상이 3가지라서 2개가 아니다."},{"번호":3,"판정":"옳음","설명":"분사무소 설치 신고(제5호), 개설등록 신청(제3호), 등록증 재교부 신청(제4호)이 해당한다."},{"번호":4,"판정":"틀림","설명":"휴업 신고와 자격증 최초 교부는 법 제47조제1항에 열거되지 않아 4개가 되지 않는다."},{"번호":5,"판정":"틀림","설명":"다섯 가지 모두가 해당하지는 않는다. 자격증은 재교부 신청 때 수수료를 낸다(법 제47조제1항제2호)."}],"개념":[{"종류":"표","제목":"수수료 납부 대상(법 제47조제1항)","머리":["호","납부 대상","수수료 결정"],"행":[["1","공인중개사자격시험 응시","지방자치단체 조례(국토교통부장관이 시행하는 시험은 장관이 결정·공고)"],["2","공인중개사자격증 재교부 신청","조례"],["3","중개사무소 개설등록 신청","조례"],["4","중개사무소등록증 재교부 신청","조례"],["5","분사무소 설치 신고","조례"],["6","분사무소설치신고확인서 재교부 신청","조례"]]},{"종류":"표","제목":"휴업·폐업·재개 신고(법 제21조, 영 제18조)","머리":["항목","내용"],"행":[["신고 대상","3개월 초과 휴업(개설등록 후 업무 미개시 포함), 폐업, 3개월 초과 휴업한 중개업 재개, 휴업기간 변경"],["신고 방법","등록관청에 미리 신고. 휴업·폐업은 등록증 첨부, 재개·변경은 전자문서 신고 가능"],["휴업 기간","6개월 초과 불가"],["예외 사유","질병으로 인한 요양, 징집으로 인한 입영, 취학, 임신 또는 출산, 이에 준하는 고시 사유"],["분사무소","법인은 분사무소별로 신고 가능(신고확인서 첨부)"],["위반","신고하지 않으면 100만원 이하 과태료(법 제51조제3항제4호), 6개월 초과 휴업은 등록취소 가능(법 제38조제2항제5호)"]]}],"함정":"자격증은 처음 교부받을 때가 아니라 재교부를 신청할 때 수수료를 낸다(제2호). 휴업 신고는 열거되어 있지 않다. 분사무소는 설치 신고(제5호)와 신고확인서 재교부 신청(제6호) 둘 다 대상이다."},"27회-2차-008":{"한줄":"분사무소는 주된 사무소의 소재지가 속한 시·군·구를 제외하고 설치하므로 ②가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제15조제1항","원문":"법 제13조제3항에 따른 분사무소는 주된 사무소의 소재지가 속한 시(구가 설치되지 아니한 시와 특별자치도의 행정시를 말한다. 이하 이 조에서 같다)ㆍ군ㆍ구를 제외한 시ㆍ군ㆍ구별로 설치하되, 시ㆍ군ㆍ구별로 1개소를 초과할 수 없다."},{"법령":"공인중개사법 시행령","조문":"영 제15조제3항","원문":"법 제13조제3항에 따라 분사무소의 설치신고를 하려는 자는 국토교통부령으로 정하는 분사무소설치신고서에 다음 각 호의 서류를 첨부하여 주된 사무소의 소재지를 관할하는 등록관청에 제출하여야 한다. 이 경우 등록관청은 법 제5조제2항에 따라 공인중개사 자격증을 발급한 시ㆍ도지사에게 분사무소 책임자의 공인중개사 자격 확인을 요청하여야 하고, 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 법인 등기사항증명서를 확인하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제15조제2항","원문":"제1항의 규정에 따른 분사무소에는 공인중개사를 책임자로 두어야 한다. 다만, 다른 법률의 규정에 따라 중개업을 할 수 있는 법인의 분사무소인 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"법 제20조제1항","원문":"개업공인중개사는 중개사무소를 이전한 때에는 이전한 날부터 10일 이내에 국토교통부령으로 정하는 바에 따라 등록관청에 이전사실을 신고하여야 한다. 다만, 중개사무소를 등록관청의 관할 지역 외의 지역으로 이전한 경우에는 이전 후의 중개사무소를 관할하는 시장ㆍ군수 또는 구청장(이하 이 조에서 \"이전후 등록관청\"이라 한다)에게 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제13조제1항제2호마목","원문":"마. 건축물대장에 기재된 건물에 중개사무소를 확보(소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법에 의하여 사용권을 확보하여야 한다)할 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"소유, 전세, 임대차, 사용대차 등 사용권을 확보하면 되고 소유권이 필수는 아니다(영 제13조제1항제1호나목)."},{"번호":2,"판정":"틀림","설명":"분사무소는 주된 사무소의 소재지가 속한 시·군·구를 제외한 곳에 설치하며 시·군·구별 1개소를 넘을 수 없다(영 제15조제1항)."},{"번호":3,"판정":"옳음","설명":"분사무소 설치신고서는 주된 사무소의 소재지를 관할하는 등록관청에 낸다(영 제15조제3항)."},{"번호":4,"판정":"옳음","설명":"다른 법률에 따라 중개업을 할 수 있는 법인의 분사무소는 공인중개사 책임자를 두지 않아도 된다(영 제15조제2항 단서)."},{"번호":5,"판정":"옳음","설명":"관할 지역 밖으로 이전하면 이전 후 중개사무소를 관할하는 등록관청에 신고한다(법 제20조제1항 단서)."}],"개념":[{"종류":"표","제목":"분사무소 설치(법 제13조제3항, 영 제15조)","머리":["항목","내용","근거"],"행":[["설치 주체","법인인 개업공인중개사","법 제13조제3항"],["설치 지역","주된 사무소 소재지가 속한 시·군·구를 제외한 시·군·구, 시·군·구별 1개소","영 제15조제1항"],["책임자","공인중개사. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외","영 제15조제2항"],["신고처","주된 사무소 소재지 관할 등록관청","영 제15조제3항"],["첨부서류","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류","영 제15조제3항제3호~제5호"],["신고확인서","적합하면 신고확인서를 교부하고 설치예정지역 관할 시장·군수·구청장에게 통보","법 제13조제4항"],["보증","분사무소마다 2억원 이상 추가 설정","영 제24조제1항제1호"]]},{"종류":"흐름","제목":"관할 밖 중개사무소 이전신고","단계":[{"이름":"이전","설명":"중개사무소를 이전. 이전한 날부터 10일 이내에 신고(법 제20조제1항)"},{"이름":"신고","설명":"이전 후 중개사무소를 관할하는 등록관청에 이전신고서, 등록증, 사용권 증명서류를 제출(법 제20조제1항 단서, 시행규칙 제11조제1항)"},{"이름":"서류 송부 요청","설명":"이전후 등록관청이 종전 등록관청에 관련 서류 송부를 요청(법 제20조제2항)"},{"이름":"서류 송부","설명":"종전 등록관청이 등록대장, 개설등록 신청서류, 최근 1년간의 행정처분 관련 서류를 송부(시행규칙 제11조제4항)"},{"이름":"등록증 재교부","설명":"적합하면 이전후 등록관청이 등록증을 재교부(시행규칙 제11조제2항)"},{"이름":"이전 전 사유 처분","설명":"신고 전에 생긴 사유에 대한 행정처분은 이전후 등록관청이 함(법 제20조제3항)"}]}],"함정":"분사무소는 주된 사무소와 같은 시·군·구에는 둘 수 없다(②). 신고 상대는 분사무소 소재지가 아니라 주된 사무소 소재지의 등록관청이다(③). 사무소 이전은 관할 밖으로 옮기면 이전 후 관할 등록관청에 신고한다(⑤)."},"27회-2차-009":{"한줄":"분사무소에서 쓸 인장은 법인 신고 인장 외에 대표자가 보증하는 인장도 등록할 수 있어 \"신고한 법인의 인장으로만\"이라고 한 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제16조제1항","원문":"개업공인중개사 및 소속공인중개사는 국토교통부령으로 정하는 바에 따라 중개행위에 사용할 인장을 등록관청에 등록하여야 한다. 등록한 인장을 변경한 경우에도 또한 같다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제1항","원문":"개업공인중개사 및 소속공인중개사는 법 제16조제1항의 규정에 따라 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제2항","원문":"제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제3항","원문":"제1항 및 제2항에 따라 개업공인중개사 및 소속공인중개사가 등록하여야 할 인장은 공인중개사인 개업공인중개사, 법 제7638호 부칙 제6조제2항에 규정된 개업공인중개사 및 소속공인중개사의 경우에는 「가족관계의 등록 등에 관한 법률」에 따른 가족관계등록부 또는 「주민등록법」에 따른 주민등록표에 기재되어 있는 성명이 나타난 인장으로서 그 크기가 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내인 인장이어야 하며, 법인인 개업공인중개사의 경우에는 「상업등기규칙」에 따라 신고한 법인의 인장이어야 한다. 다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제4항","원문":"법인인 개업공인중개사의 제1항 및 제2항에 따른 인장 등록은 「상업등기규칙」에 따른 인감증명서의 제출로 갈음한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 업무를 개시하기 전에 인장을 등록관청에 등록한다(시행규칙 제9조제1항)."},{"번호":2,"판정":"옳음","설명":"등록한 인장을 변경하면 변경일부터 7일 이내에 변경된 인장을 등록한다(시행규칙 제9조제2항)."},{"번호":3,"판정":"옳음","설명":"공인중개사인 개업공인중개사와 소속공인중개사의 인장은 가로·세로 각각 7밀리미터 이상 30밀리미터 이내다(시행규칙 제9조제3항)."},{"번호":4,"판정":"틀림","설명":"분사무소에서 사용할 인장은 법인의 대표자가 보증하는 인장도 등록할 수 있다(시행규칙 제9조제3항 단서)."},{"번호":5,"판정":"옳음","설명":"법인인 개업공인중개사의 인장 등록은 인감증명서 제출로 갈음한다(시행규칙 제9조제4항)."}],"개념":[{"종류":"표","제목":"인장등록(법 제16조, 시행규칙 제9조)","머리":["항목","내용","근거"],"행":[["등록 대상자","개업공인중개사, 소속공인중개사","법 제16조제1항"],["등록 시기","업무를 개시하기 전","시행규칙 제9조제1항"],["변경 등록","변경일부터 7일 이내","시행규칙 제9조제2항"],["사용 의무","중개행위를 할 때 등록한 인장 사용","법 제16조제2항"],["함께 할 수 있는 신청","개설등록 신청, 소속공인중개사·중개보조원 고용 신고와 같이 등록 가능","시행규칙 제9조제6항"],["위반 제재","개업공인중개사는 업무정지, 소속공인중개사는 자격정지","법 제39조제1항제2호, 제36조제1항제2호"]]},{"종류":"비교","제목":"등록하는 인장의 종류(시행규칙 제9조제3항·제4항)","왼쪽":{"이름":"공인중개사인 개업공인중개사·소속공인중개사","항목":["가족관계등록부 또는 주민등록표에 기재된 성명이 나타난 인장","가로·세로 각각 7밀리미터 이상 30밀리미터 이내"]},"오른쪽":{"이름":"법인인 개업공인중개사","항목":["「상업등기규칙」에 따라 신고한 법인의 인장","인장 등록은 인감증명서 제출로 갈음","분사무소에서 쓸 인장은 법인 대표자가 보증하는 인장도 등록 가능"]}}],"함정":"법인의 인장은 원칙적으로 상업등기규칙에 따라 신고한 법인 인장이지만 분사무소는 예외가 있다. 선지의 \"으로만\"이 예외를 막아 버린다. 크기(7~30밀리미터)와 변경 기한(7일)은 숫자 그대로 맞다."},"27회-2차-011":{"한줄":"옥외광고물에는 연락처가 아니라 개업공인중개사의 성명을 표기하고, 연락처 미표기를 과태료 대상으로 한 ③이 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제18조제1항","원문":"개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용하여야 한다."},{"법령":"공인중개사법","조문":"법 제18조제3항","원문":"개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제10조의2","원문":"개업공인중개사는 법 제18조제3항에 따라 옥외광고물을 설치하는 경우 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률 시행령」 제3조에 따른 옥외광고물 중 벽면 이용간판, 돌출간판 또는 옥상간판에 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 법 제13조제4항에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 인식할 수 있는 정도의 크기로 표기해야 한다."},{"법령":"공인중개사법","조문":"법 제18조제5항","원문":"등록관청은 제1항부터 제3항까지의 규정을 위반한 사무소의 간판 등에 대하여 철거를 명할 수 있다. 이 경우 그 명령을 받은 자가 철거를 이행하지 아니하는 경우에는 「행정대집행법」에 의하여 대집행을 할 수 있다."},{"법령":"공인중개사법","조문":"법 제18조의2제3항","원문":"개업공인중개사가 아닌 자는 중개대상물에 대한 표시ㆍ광고를 하여서는 아니 된다."},{"법령":"공인중개사법","조문":"법 제51조제3항제2호","원문":"다음 각 호의 어느 하나에 해당하는 자에게는 100만원 이하의 과태료를 부과한다. 제18조제1항 또는 제3항을 위반하여 사무소의 명칭에 \"공인중개사사무소\", \"부동산중개\"라는 문자를 사용하지 아니한 자 또는 옥외 광고물에 성명을 표기하지 아니하거나 거짓으로 표기한 자"}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 법인이든 아니든 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"를 사용해야 한다(법 제18조제1항)."},{"번호":2,"판정":"옳음","설명":"옥외광고물은 설치하는 경우에 성명 표기 의무가 생길 뿐 설치 자체의 의무는 없다(법 제18조제3항)."},{"번호":3,"판정":"틀림","설명":"옥외광고물에 표기할 사항은 개업공인중개사의 성명이다(법 제18조제3항, 시행규칙 제10조의2). 과태료는 성명을 표기하지 않거나 거짓으로 표기한 경우에 부과한다(법 제51조제3항제2호)."},{"번호":4,"판정":"옳음","설명":"개업공인중개사가 아닌 자의 간판은 등록관청이 철거를 명할 수 있다(법 제18조제5항)."},{"번호":5,"판정":"옳음","설명":"개업공인중개사가 아닌 자는 중개대상물에 대한 표시·광고를 해서는 안 된다(법 제18조의2제3항)."}],"개념":[{"종류":"표","제목":"중개사무소 명칭과 표시·광고(법 제18조, 제18조의2)","머리":["항목","내용","근거"],"행":[["명칭","개업공인중개사는 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\" 사용","법 제18조제1항"],["명칭 금지","개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 유사 명칭 사용 금지","법 제18조제2항"],["옥외광고물","설치하는 경우 등록증에 표기된 개업공인중개사 성명 표기(법인은 대표자, 분사무소는 신고확인서의 책임자). 설치 자체는 의무 아님","법 제18조제3항, 시행규칙 제10조의2"],["철거","위반 간판은 등록관청이 철거를 명하고 이행하지 않으면 행정대집행","법 제18조제5항"],["표시·광고 명시","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자). 중개보조원 사항은 명시 금지","법 제18조의2제1항, 영 제17조의2제1항"],["표시·광고 주체","개업공인중개사가 아닌 자는 중개대상물 표시·광고 금지","법 제18조의2제3항"],["제재","명칭 미사용·성명 미표기 100만원 이하 과태료, 명칭 무자격 사용 1년 이하 징역 또는 1천만원 이하 벌금","법 제51조제3항제2호, 제49조제1항제6호"]]},{"종류":"표","제목":"중개사무소 안에 게시할 사항(법 제17조, 시행규칙 제10조)","머리":["호","게시 사항"],"행":[["1","중개사무소등록증 원본(분사무소는 분사무소설치신고확인서 원본)"],["2","중개보수·실비의 요율 및 한도액표"],["3","개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당자가 있는 경우)"],["4","보증의 설정을 증명할 수 있는 서류"],["5","「부가가치세법 시행령」 제11조에 따른 사업자등록증"],["위반","게시하지 않으면 100만원 이하 과태료(법 제51조제3항제1호)"]]}],"함정":"옥외광고물 표기 사항은 성명이고 연락처가 아니다. 연락처는 중개대상물 표시·광고 때 명시할 사항(영 제17조의2제1항)이라서 장면이 다르다. 설치가 의무가 아니라는 점(②)과 무자격자 간판의 철거명령(④)은 조문대로다."},"27회-2차-012":{"한줄":"폐업신고를 한 개업공인중개사는 간판을 \"1개월 이내\"가 아니라 지체 없이 철거해야 하므로 ④가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제18조제1항제1호","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우"},{"법령":"공인중개사법 시행령","조문":"영 제18조제6항제3호","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. 취학"},{"법령":"공인중개사법 시행령","조문":"영 제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다. 1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우 2. 폐업하려는 경우 3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우 4. 신고한 휴업기간을 변경하려는 경우"},{"법령":"공인중개사법","조문":"법 제21조의2제1항제2호","원문":"개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 사무소의 간판을 철거하여야 한다. 제21조제1항에 따라 등록관청에 폐업사실을 신고한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제18조제5항","원문":"제1항 또는 제2항에 따른 중개사무소재개신고를 받은 등록관청은 반납받은 중개사무소등록증 또는 신고확인서를 즉시 반환해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"휴업 신고 대상은 3개월을 초과하는 휴업이므로 2개월 휴업은 신고 의무가 없다(영 제18조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"취학은 부득이한 사유라서 6개월을 초과하여 휴업할 수 있다(영 제18조제6항제3호, 법 제21조제2항 단서)."},{"번호":3,"판정":"옳음","설명":"휴업기간 변경신고는 전자문서에 의한 신고를 포함한다(영 제18조제1항 본문)."},{"번호":4,"판정":"틀림","설명":"폐업사실을 신고한 경우에는 지체 없이 간판을 철거해야 한다(법 제21조의2제1항제2호). 1개월이라는 기한은 조문에 없다."},{"번호":5,"판정":"옳음","설명":"중개사무소재개신고를 받은 등록관청은 반납받은 등록증을 즉시 반환해야 한다(영 제18조제5항)."}],"개념":[{"종류":"흐름","제목":"휴업·재개·폐업 신고","단계":[{"이름":"휴업 신고","설명":"3개월을 초과하는 휴업은 등록관청에 미리 신고하고 등록증을 첨부(영 제18조제1항제1호)"},{"이름":"휴업 기간","설명":"6개월을 초과할 수 없음. 질병 요양, 징집 입영, 취학, 임신·출산 등은 예외(법 제21조제2항, 영 제18조제6항)"},{"이름":"기간 변경","설명":"신고한 휴업기간을 바꾸려면 미리 신고. 전자문서 신고 가능(영 제18조제1항제4호)"},{"이름":"재개 신고","설명":"3개월을 초과하여 휴업한 중개업을 재개하려면 미리 신고. 등록관청은 반납받은 등록증을 즉시 반환(영 제18조제1항제3호·제5항)"},{"이름":"폐업 신고","설명":"폐업하려면 미리 신고하고 등록증 첨부. 신고 후 간판은 지체 없이 철거(영 제18조제1항제2호, 법 제21조의2제1항)"}]},{"종류":"표","제목":"사무소 간판의 철거","머리":["구분","내용","근거"],"행":[["철거 사유","중개사무소 이전사실 신고","법 제21조의2제1항제1호"],["철거 사유","폐업사실 신고","법 제21조의2제1항제2호"],["철거 사유","개설등록 취소처분을 받은 경우","법 제21조의2제1항제3호"],["철거 시기","지체 없이","법 제21조의2제1항"],["불이행","등록관청이 행정대집행","법 제21조의2제2항"],["무자격자 간판","공인중개사사무소·부동산중개 또는 유사 명칭 간판은 등록관청이 철거를 명하고 대집행 가능","법 제18조제5항"]]}],"함정":"간판 철거 기한은 지체 없이다. 휴업은 3개월 초과부터 신고 대상이라 2개월은 신고하지 않는다. 취학 같은 부득이한 사유가 있으면 6개월을 넘겨도 된다."}};